function multiviewStage1(){return title('More windows. More wonder.','Bring your favorite creators together in one place.','MAGICAL MULTIVIEW')+`<div class="toolbar"><button id="two" class="${prefs.screens!==4?'active':''}">Two screens</button><button id="four" class="${prefs.screens===4?'active':''}">Four screens</button><button id="addStream">＋ Save a stream</button></div><div class="streamgrid">${Array.from({length:prefs.screens===4?4:2},(_,i)=>{let s=prefs.streams[i];return `<article class="streamtile">${s?embed(s,i):`<div class="copy"><p class="eyebrow">WINDOW ${i+1}</p><h2>A little magic belongs here.</h2><p>Save a YouTube video or direct MP4/HLS stream. A Paris parade, a resort walk, or fireworks over the lagoon.</p><button data-streamslot="${i}">＋ Choose this view</button></div>`}${s?`<div class="copy"><h3>${esc(s.name)}</h3><p>${esc(s.kind)} · availability controlled by the broadcaster</p><button data-streamslot="${i}">Change</button> <button data-remove="${i}">Remove</button></div>`:''}</article>`}).join('')}</div><div class="bottomnote">Streams start muted so four windows don’t compete. Use each player’s volume control to hear one. Embedding may be disabled by a creator; HLS playback depends on your browser. Saved links are not verified as live.</div><h2 style="margin-top:25px">Find your next park window</h2><div class="buttons"><a class="pill" href="https://www.youtube.com/@ResortTV1/streams" target="_blank" rel="noopener">ResortTV1 ↗</a><a class="pill" href="https://www.youtube.com/@ParkPassTV/streams" target="_blank" rel="noopener">Park Pass TV ↗</a></div><p class="muted">Save a specific video’s link above. Automatic live discovery and a continuous Orlando skyline camera require a configured broadcast source.</p>`}
function videoID(url){try{const u=new URL(url);if(u.hostname==='youtu.be')return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(/^(www\.|m\.)?youtube\.com$/.test(u.hostname)){const id=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean)[1];return /^[\w-]{11}$/.test(id)?id:null}}catch{}return null}function embed(s,i){const id=videoID(s.url);return id?`<iframe title="${esc(s.name)}" src="https://www.youtube-nocookie.com/embed/${id}?autoplay=0&mute=1" allow="autoplay; encrypted-media; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`:`<video controls muted playsinline preload="none" src="${esc(s.url)}" aria-label="${esc(s.name)}"></video>`}
function pianoStage1(){return title('A little jazz. A little joy.','An intimate corner of your happy place, inspired by French Quarter evenings.','THE PIANO LOUNGE')+`<div class="welcome" style="background:radial-gradient(ellipse at top,#654934,#211c2b)"><p class="eyebrow">THE SPARKLE SESSIONS</p><h1>Stay for one more song.</h1><p class="muted">Play a few notes, or unwind with an original synthesized lounge loop.</p><button class="primary" id="ambience">${musicTimer?'Pause ambience':'♬ Start the lounge'}</button><div class="pianokeys">${['C','D','E','F','G','A','B','C'].map((n,i)=>`<button data-note="${i}" aria-label="Play ${n}">${n}</button>`).join('')}</div></div><div class="card" style="margin-top:20px"><h2>Your request list</h2><p class="muted">Keep a wish list for your next piano night. Requests are saved on this device; they are not sent to a performer.</p><form id="requestForm" class="toolbar"><input id="song" required maxlength="150" placeholder="What would you love to hear?" aria-label="Song request"><button class="primary">Add to my requests</button></form><div>${(prefs.requests||[]).map((r,i)=>`<p>♬ &nbsp; ${esc(r)} <button data-remove-request="${i}">Remove</button></p>`).join('')}</div><p class="muted">Monthly live shows need a performer and broadcast schedule. Add an actual show’s video in Magical multiview when one is available.</p></div>`}
function vacation(){return title('The magic is getting closer.','Every sleep brings you one day closer to your happy place.','YOUR VACATION COUNTDOWN')+`<section class="welcome"><p class="eyebrow">${esc(prefs.family)} · YOUR NEXT DISNEY ADVENTURE</p><div class="countdown">${days()===null?'Let’s dream.':days()===0?'It’s time!':days()+' sleeps'}</div><h2>${prefs.date?esc(new Date(prefs.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'})):'A date with a little magic.'}</h2><p>${esc(prefs.resort)}</p><div class="toolbar" style="justify-content:center"><input type="date" id="tripDate" value="${esc(prefs.date)}" aria-label="Vacation arrival date"><button id="saveDate" class="primary">Save my countdown</button><button id="celebrate">✧ Celebrate with fireworks</button></div></section>`}
function settingsStage1(){return title('Make this little world yours.','A name, a resort, a date. You’re ready for the magic.','TWO-MINUTE SETUP')+`<form id="settingsForm" class="settings card"><div class="formgrid"><label>Your first name<input name="name" value="${esc(prefs.name)}" required maxlength="50"></label><label>Welcome screen name<input name="family" value="${esc(prefs.family)}" required maxlength="70"></label><label>Your Disney resort<select name="resort">${resorts.map(r=>`<option ${prefs.resort===r?'selected':''}>${esc(r)}</option>`).join('')}</select></label><label>Your next vacation<input type="date" name="date" value="${esc(prefs.date)}"></label><label><input type="checkbox" name="clock24" ${prefs.clock24?'checked':''}>24-hour clock</label></div><div class="toolbar"><button class="primary">Save my sparkle</button></div><p class="muted">Settings, favorites, and stream links stay in this browser. Photos stay on this device. No account or API key needed for the park feed.</p></form><div class="card settings" style="margin-top:20px"><h2>Your big-screen happy place</h2><p class="muted">Open this app in your TV’s browser, connect a computer with HDMI, or mirror your screen. On iPhone/iPad, use Control Center → Screen Mirroring with an AirPlay-compatible TV. In Chrome, use the browser’s Cast option.</p><button id="tvSettings">Enter TV display</button><p class="muted">TV mode enlarges the experience and requests a screen wake lock where supported. Press Escape to exit. The app does not pair with a TV or act as a separate remote.</p></div>`}
async function photos(){const data=await photoStore('get');photoUrls.forEach(URL.revokeObjectURL);photoUrls=data.map(x=>URL.createObjectURL(x.blob));if(page!=='photos')return;$('#main').innerHTML=title('The moments you take home.','Your favorite memories, ready for another little escape.','YOUR MEMORY WALL')+`<label class="card">Add vacation photos<input id="upload" type="file" accept="image/*" multiple></label><div class="photogrid" style="margin-top:20px">${data.map((p,i)=>`<div><img src="${photoUrls[i]}" alt="${esc(p.name)}"><button data-delete-photo="${p.id}">Remove photo</button></div>`).join('')}</div><p class="muted">Photos stay in this browser unless you upload them using Family sync. Clearing website data removes local copies.</p>`;$('#upload').onchange=async e=>{for(const f of e.target.files){if(f.size>12e6){toast('Choose images under 12 MB.');continue}try{await photoStore('put',{id:crypto.randomUUID(),name:f.name,blob:f})}catch{toast('Could not save photo. Device storage may be full.')}}photos()};document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{await photoStore('delete',b.dataset.deletePhoto);photos()});installMagic();installGuide();installFamilyTools()}
function photoStore(mode,value){return new Promise((resolve,reject)=>{let req=indexedDB.open('sparkle-photos',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos',{keyPath:'id'});req.onerror=()=>reject(req.error);req.onsuccess=()=>{const db=req.result,tx=db.transaction('photos',mode==='get'?'readonly':'readwrite'),st=tx.objectStore('photos'),r=mode==='get'?st.getAll():mode==='put'?st.put(value):st.delete(value);r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error);tx.oncomplete=()=>db.close()}})}
