function streamDialog(i){$('#dialog').innerHTML=`<h2>A new window into the magic</h2><form id="streamForm"><label>Give this view a name<input name="name" required maxlength="80" value="${esc(prefs.streams[i]?.name||'')}" placeholder="An evening at Magic Kingdom"></label><br><label>YouTube video or HTTPS video URL<input name="url" type="url" required value="${esc(prefs.streams[i]?.url||'')}" placeholder="https://www.youtube.com/watch?v=…"></label><br><label>What kind of video?<select name="kind"><option>Creator stream · live status unverified</option><option>Recorded park visit</option><option>Resort tour</option><option>Piano show</option></select></label><div class="toolbar"><button class="primary">Save view ${i+1}</button><button type="button" id="cancel">Cancel</button></div><p class="muted">Use a public video that permits embedding. Direct HLS playback is supported natively by Safari; other browsers may need a different source.</p></form>`;$('#dialog').showModal();$('#cancel').onclick=()=>$('#dialog').close();$('#streamForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),u=new URL(d.url);if(u.protocol!=='https:'||(!videoID(d.url)&&! /\.(mp4|m3u8|webm)$/i.test(u.pathname))){toast('Use a YouTube video link or HTTPS MP4, WebM, or HLS URL.');return}prefs.streams[i]=d;save();$('#dialog').close();render()}}
async function api(path){if(Date.now()<blockedUntil)throw new Error('The data provider is rate limiting requests. Please wait before refreshing.');if(requests.has(path))return requests.get(path);const promise=(async()=>{const r=await fetch(API+path,{signal:AbortSignal.timeout(15000)});if(r.status===429){blockedUntil=Date.now()+Math.max(60,Number(r.headers.get('Retry-After'))||60)*1000;throw new Error('Park data is temporarily rate limited. Automatic retries will wait.')}if(!r.ok)throw new Error('Park data service returned '+r.status);return r.json()})();requests.set(path,promise);try{return await promise}finally{requests.delete(path)}}
async function initData(){try{let d=await api('/destinations');parks=d.destinations.filter(x=>/disney|universal orlando|knott/i.test(x.name)).flatMap(x=>x.parks.map(p=>({...p,destination:x.name})));parks.sort((a,b)=>(/Walt Disney World/.test(b.destination)?1:0)-(/Walt Disney World/.test(a.destination)?1:0));if(!parks.some(p=>p.id===selected)&&parks.length)selected=parks[0].id;if(['parks','resort','terrace'].includes(page))render();loadPark()}catch(e){errors[selected]='Park connection unavailable. Check your internet connection and try Refresh.';if(page==='parks')render()}}
async function loadPark(force=false){const id=selected;if(!force&&live[id]&&Date.now()-live[id].at<60000)return;const outcomes=await Promise.allSettled([api('/entity/'+id+'/live'),!schedules[id]||force?api('/entity/'+id+'/schedule'):Promise.resolve(null)]);if(outcomes[0].status==='fulfilled'){live[id]={data:outcomes[0].value.liveData||[],at:Date.now()};delete errors[id]}else errors[id]=outcomes[0].reason.message||'Park data is unavailable.';if(outcomes[1].status==='fulfilled'&&outcomes[1].value)schedules[id]=outcomes[1].value.schedule||[];if(selected===id&&['parks','resort','terrace'].includes(page))render()}
function note(freq,duration=1.5,volume=.08){audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime,osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='triangle';osc.frequency.value=freq;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(volume,t+.015);gain.gain.exponentialRampToValueAtTime(.001,t+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(t);osc.stop(t+duration)}
function toggleMusic(){if(musicTimer){clearInterval(musicTimer);musicTimer=null;return}let n=0;const chords=[[130.81,164.81,196,246.94],[110,130.81,164.81,196],[146.83,174.61,220,261.63],[98,123.47,146.83,174.61]];const play=()=>{let chord=chords[Math.floor(n/4)%4];note(chord[n%4],2.5,.04);if(n%4===0)note(chord[0]/2,3,.025);n++};play();musicTimer=setInterval(play,650)}
let wake;async function tv(){document.body.classList.add('tv');if(!$('#exitTV')){let b=document.createElement('button');b.id='exitTV';b.textContent='Exit TV mode';b.onclick=exitTV;document.body.append(b)}try{await document.documentElement.requestFullscreen()}catch{}try{wake=await navigator.wakeLock?.request('screen')}catch{}}function exitTV(){document.body.classList.remove('tv');$('#exitTV')?.remove();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});wake?.release()}document.addEventListener('keydown',e=>{if(e.key==='Escape')exitTV()});$('#tv').onclick=tv;
function animate(){const canvas=$('#fireworks');if(!canvas)return;const ctx=canvas.getContext('2d');let w,h,particles=[],last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function resize(){w=canvas.width=canvas.clientWidth;h=canvas.height=canvas.clientHeight}resize();function frame(t){if(!canvas.isConnected)return;ctx.clearRect(0,0,w,h);let active=page==='home'?!reduced:show;if(active&&t-last>(reduced?2400:1100)){last=t;let x=w*(.35+Math.random()*.5),y=h*(.12+Math.random()*.28),color=['#ebc88a','#cea8e7','#a4c5ef','#f2a9c3'][Math.floor(Math.random()*4)];for(let i=0;i<65;i++){let a=Math.PI*2*i/65,v=1+Math.random()*1.5;particles.push({x,y,px:x,py:y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1,color})}}for(let p of particles){p.px=p.x;p.py=p.y;p.x+=p.vx;p.y+=p.vy;p.vy+=.015;p.vx*=.992;p.life-=.009;ctx.globalAlpha=Math.max(0,p.life);ctx.strokeStyle=p.color;ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(p.px,p.py);ctx.lineTo(p.x,p.y);ctx.stroke()}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);raf=requestAnimationFrame(frame)}raf=requestAnimationFrame(frame)}
let fired=new Set();setInterval(()=>{$('#clock').textContent=new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',hour12:!prefs.clock24,timeZone:'America/New_York'})+' · Orlando';if(prefs.schedule){for(const s of getItems().filter(x=>/happily ever after|firework|luminous|wondrous|disney tales|not.so.spooky|christmastime/i.test(x.name))){for(const t of s.showtimes||[]){let dt=Date.now()-new Date(t.startTime).getTime(),key=s.id+t.startTime;if(dt>=0&&dt<60000&&!fired.has(key)){fired.add(key);show=true;navigate('terrace');toast('The published showtime has arrived. Press Play to start the selected show; browsers may require a tap.')}}}}},1000);setInterval(()=>{if(!document.hidden)loadPark()},90000);setInterval(()=>{if(!prefs.auto||document.hidden)return;if(page==='parks'&&sign){signIndex++;render()}else if(page==='resort'&&parks.length){selected=parks[(parks.findIndex(p=>p.id===selected)+1)%parks.length].id;render();loadPark()}},12000);


