const norm=s=>(s||'').toLowerCase().replace(/disney['’]?s|disney|walt|park|resort|®|™/g,'').replace(/[^a-z0-9]/g,'');
function queuePark(){const p=parks.find(x=>x.id===selected);if(!p)return null;return queueParks.find(q=>q.name===p.name)||queueParks.find(q=>norm(q.name)===norm(p.name));}
async function getJSON(url){const r=await fetch(url,{signal:AbortSignal.timeout(14000),cache:'no-cache'});if(!r.ok){if(r.status===429)blockedUntil=Date.now()+Math.max(60,Number(r.headers.get('Retry-After'))||60)*1000;throw Error('Feed unavailable ('+r.status+')')}return r.json()}
async function routed(local,direct){try{return await getJSON(local)}catch(e){if(Date.now()<blockedUntil)throw e;return getJSON(direct)}}
api=async function(path){if(Date.now()<blockedUntil)throw Error('Provider rate limit: please wait before refreshing.');if(requests.has(path))return requests.get(path);const task=routed('/api/themeparks'+path,API+path);requests.set(path,task);try{return await task}finally{requests.delete(path)}};
function isFresh(r,now=Date.now()){const t=Date.parse(r.lastUpdated);return Number.isFinite(t)&&now-t<=MAX_AGE&&t-now<=120000}
function normalQueue(data){const rows=[...(data.rides||[]),...(data.lands||[]).flatMap(l=>(l.rides||[]).map(r=>({...r,land:l.name})))];return [...new Map(rows.map(r=>['qt-'+r.id,{id:'qt-'+r.id,name:r.name,land:r.land||'',entityType:'ATTRACTION',status:r.is_open===true?'OPERATING':r.is_open===false?'NOT_OPERATING':'UNKNOWN',lastUpdated:r.last_updated,source:'Queue-Times',queue:{STANDBY:{waitTime:typeof r.wait_time==='number'&&r.wait_time>=0?r.wait_time:null}}}])).values()]}
function sourceScore(rows){const a=rows.filter(r=>r.entityType==='ATTRACTION');return a.length?a.filter(r=>isFresh(r)).length/a.length:0}
function chooseReadings(q,t){if(q?.length&&sourceScore(q)>=.5)return {rows:q,source:'Queue-Times'};if(t?.length&&sourceScore(t)>=.5)return {rows:t.filter(r=>r.entityType==='ATTRACTION').map(r=>({...r,source:'ThemeParks.wiki'})),source:'ThemeParks.wiki fallback'};if(q?.length)return {rows:q,source:'Queue-Times · stale or untimed'};if(t?.length)return {rows:t.filter(r=>r.entityType==='ATTRACTION'),source:'ThemeParks.wiki · stale or untimed'};return null}
loadPark=async function(force=false){const id=selected;if(feedBusy||Date.now()<blockedUntil)return;if(!force&&live[id]&&Date.now()-live[id].at<60000)return;feedBusy=true;const q=queuePark();try{const results=await Promise.allSettled([q?routed('/api/queue/parks/'+q.id,'https://queue-times.com/parks/'+q.id+'/queue_times.json'):Promise.resolve(null),api('/entity/'+id+'/live'),!scheduleFetched[id]||Date.now()-scheduleFetched[id]>300000?api('/entity/'+id+'/schedule'):Promise.resolve(null)]);const qrows=results[0].status==='fulfilled'&&results[0].value?normalQueue(results[0].value):null;const trows=results[1].status==='fulfilled'?results[1].value.liveData||[]:null;const chosen=chooseReadings(qrows,trows);if(chosen){live[id]={data:[...chosen.rows,...(trows||[]).filter(r=>r.entityType!=='ATTRACTION')],at:Date.now(),source:chosen.source};delete errors[id];if(sourceScore(chosen.rows)<.5)errors[id]='The provider’s readings are stale or lack timestamps. Current status is unknown; old readings are shown only for context.';}else errors[id]='Both data sources are unavailable. A connection failure does not mean the park is closed.';if(results[2].status==='fulfilled'&&results[2].value){schedules[id]=results[2].value.schedule||[];scheduleFetched[id]=Date.now()}sampleWaits(id)}finally{feedBusy=false;if(selected===id&&['home','parks','resort','terrace','insights'].includes(page)&&!(page==='terrace'&&videoStarted))render();else if(selected!==id)loadPark()}};
initData=async function(){await Promise.allSettled([(async()=>{const d=await routed('/api/queue/parks','https://queue-times.com/parks.json');queueParks=d.flatMap(g=>g.parks||[]);queueReady=true})(),(async()=>{const d=await api('/destinations');parks=d.destinations.filter(x=>/disney|universal orlando|knott/i.test(x.name)).flatMap(x=>x.parks.map(p=>({...p,destination:x.name})));parks.sort((a,b)=>(/Walt Disney World/.test(b.destination)?1:0)-(/Walt Disney World/.test(a.destination)?1:0))})()]);if(!parks.length&&queueParks.length){parks=queueParks.filter(p=>/disney|epcot|magic kingdom/i.test(p.name)).map(p=>({...p,id:'queue-'+p.id,destination:p.country||'',queueOnly:true}));selected=parks.find(p=>p.name.includes('Magic Kingdom'))?.id||parks[0]?.id||selected;const oldQP=queuePark;queuePark=function(){return parks.find(p=>p.id===selected)?.queueOnly?queueParks.find(p=>'queue-'+p.id===selected):oldQP()}}if(['parks','resort','insights'].includes(page))render();alignTripPark();await loadPark(true)};
waitValue=function(r){if(!isFresh(r))return '—';return r.status==='OPERATING'?(r.queue?.STANDBY?.waitTime??'—'):{DOWN:'Paused',CLOSED:'Closed',NOT_OPERATING:'Not running',REFURBISHMENT:'Refurb'}[r.status]||'—'};
freshness=function(){const d=live[selected];return d?`${esc(d.source||'ThemeParks.wiki')} · checked ${time(d.at)} · ${d.data.filter(r=>r.entityType==='ATTRACTION'&&isFresh(r)).length} fresh readings. Readings older than 15 minutes are excluded.`:'Connecting to Queue-Times and ThemeParks.wiki…'};
function parkStatus(){const now=Date.now(),rows=getItems().filter(r=>r.entityType==='ATTRACTION');const current=rows.filter(r=>isFresh(r));const open=current.filter(r=>r.status==='OPERATING');const periods=(schedules[selected]||[]).filter(s=>s.type==='OPERATING');const inHours=periods.some(s=>Date.parse(s.openingTime)<=now&&Date.parse(s.closingTime)>now);if(open.length)return `${open.length} attractions reporting open`;if(inHours)return 'Scheduled open · ride feed needs checking';return current.length?'No attractions reporting open · check park hours':'Current park status unavailable'}
const parkPageStage2=function(){let html=oldPark();html=html.replace('<div class="toolbar">',`<div class="statusstrip"><strong>${parkStatus()}</strong><span>Park hours and individual ride status are separate.</span></div><div class="toolbar">`);html=html.replaceAll("${esc(r.status||'Unknown')}",'');return html.replace(/<small class="muted">(OPERATING|CLOSED|NOT_OPERATING|DOWN|REFURBISHMENT|UNKNOWN) · ([^<]*)<\/small>/g,(all,status,t)=>`<small class="muted">Last reported: ${status.replaceAll('_',' ').toLowerCase()} · ${t}</small>`)};
