let loungeAC=null,loungeMaster=null;
function loungeContext(){loungeAC ||= new (window.AudioContext||window.webkitAudioContext)();if(!loungeMaster){loungeMaster=loungeAC.createGain();loungeMaster.gain.value=.55;loungeMaster.connect(loungeAC.destination)}loungeAC.resume();return loungeAC}
const LOUNGE={on:false,next:0,step:0,bar:0,seed:7,timer:null,styles:{lounge:{bpm:96,swing:.63,vel:1},ballad:{bpm:70,swing:.55,vel:.8},swing:{bpm:134,swing:.66,vel:1.05}},prog:[[57,[60,64,67,71]],[62,[62,65,69,72]],[55,[59,62,67,71]],[48,[60,64,67,74]]],scale:[57,60,62,64,67,69,72,74,76,79],note(m,t,dur,vel,bass=false){const a=loungeAC,o=a.createOscillator(),o2=a.createOscillator(),g=a.createGain(),g2=a.createGain();o.type=bass?'sine':'triangle';o2.type='sine';o.frequency.value=440*2**((m-69)/12);o2.frequency.value=o.frequency.value*2;g2.gain.value=bass?0:.25;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vel,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);o2.connect(g2);g2.connect(g);g.connect(loungeMaster);o.start(t);o2.start(t);o.stop(t+dur+.05);o2.stop(t+dur+.05)},tick(){if(!LOUNGE.on)return;const p=LOUNGE,sty=p.styles[pianoStyle],spb=60/sty.bpm/2;while(p.next<loungeAC.currentTime+.4){const t=p.next,e=p.step%8,chord=p.prog[p.bar%4];if(e===0){p.note(chord[0]-12,t,spb*7,.45,true);chord[1].forEach(n=>p.note(n,t+spb*(2+p.seed%2),spb*3,.08))}if(e===4)p.note(chord[0]-12+(p.seed%3===0?7:0),t,spb*3,.3,true);const r=Math.abs(Math.sin(p.seed*9301+p.step*49297)%1);if(r>.38)p.note(p.scale[Math.floor(r*p.scale.length)%p.scale.length]+12,t,spb*1.8,.14*sty.vel);p.next+=spb*2*(e%2===0?sty.swing:1-sty.swing);p.step++;if(p.step%8===0)p.bar++}},start(){stopAmbience();pianoPlaying?.pause?.();loungeContext();this.on=true;this.next=loungeAC.currentTime+.1;clearInterval(this.timer);this.timer=setInterval(()=>this.tick(),120)},stop(){this.on=false;clearInterval(this.timer);if(loungeAC)loungeAC.suspend().catch(()=>{})}};
function songKey(s){return s.toLowerCase().replace(/[^a-z0-9]/g,'')}
function pianoStage2(){return title('Tonight at the Sparkle Lounge.','The richer lounge engine from your reference app, plus a library for real recorded requests.','PIANO BAR')+`<section class="welcome piano-room"><p class="eyebrow">TAKE A SEAT. STAY FOR ANOTHER SONG.</p><h1>A little music. A little magic.</h1><div class="toolbar" style="justify-content:center"><button id="loungePlay" class="primary">${LOUNGE.on?'Pause':'Start'} the lounge set</button><select id="loungeStyle" aria-label="Piano style">${[['lounge','Lounge'],['ballad','Ballad'],['swing','Upbeat swing']].map(([v,n])=>`<option value="${v}" ${v===pianoStyle?'selected':''}>${n}</option>`).join('')}</select><button id="recordedSong">＋ Add a real piano recording</button></div><p class="muted small">Lounge mode is generated improvisation. Recorded requests play the exact track from your library.</p><form id="pianoRequest" class="toolbar" style="justify-content:center"><input name="request" placeholder="Request a song or a mood…" required maxlength="150" aria-label="Piano request"><button class="primary">Make a request</button></form><div class="request-bubbles">${(prefs.pianoQueue||[]).slice(-5).reverse().map(q=>`<div class="request-bubble">“${esc(q.name)}”<small>— ${esc(q.guest)} · ${q.track?'Recording queued':'No recording matched'}</small></div>`).join('')}</div><div id="pianoAudioMount"></div><div class="toolbar" style="justify-content:center"><button id="playNext">▶ Play next recorded request</button></div></section><h2 style="margin-top:25px">Your recorded piano library</h2><div class="resortgrid">${prefs.pianoLibrary.map(t=>`<article class="card"><h3>${esc(t.name)}</h3><button data-track="${t.id}">Play recording</button></article>`).join('')||'<p class="muted">Add authorized recordings to hear exact song requests. No piano recordings were included in the reference app.</p>'}</div>`}
async function playTrack(id){const t=prefs.pianoLibrary.find(x=>x.id===id);if(!t)return;LOUNGE.stop();try{const src=await mediaURL(t.src);$('#pianoAudioMount').innerHTML='<audio id="pianoRecording" controls></audio>';pianoPlaying=$('#pianoRecording');pianoPlaying.src=src;pianoPlaying.onended=playNextRequest;pianoPlaying.onerror=()=>toast('Recording unavailable. Check its URL or replace the file.');await pianoPlaying.play()}catch{toast('Tap the audio player to start the recording.')}}
function playNextRequest(){const i=prefs.pianoQueue.findIndex(q=>q.track&&!q.played);if(i<0){toast('No recorded requests waiting.');return}const q=prefs.pianoQueue[i];q.played=true;save();playTrack(q.track)}
function bindExperience(){if($('#checkinForm'))$('#checkinForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);for(const k of ['name','family','resort','date'])prefs[k]=d.get(k).trim();prefs.checkedIn=true;save();navigate('home')};if($('#familyCheckin'))$('#familyCheckin').onclick=()=>navigate('checkin');if($('#previewMode'))$('#previewMode').onclick=()=>{playMode='preview';render()};if($('#fullMode'))$('#fullMode').onclick=()=>{LOUNGE.stop();playMode='full';render()};if($('#mediaConfig'))$('#mediaConfig').onclick=()=>mediaDialog('video');if($('#resortQuick'))$('#resortQuick').onchange=e=>{prefs.resort=e.target.value;prefs.theme='auto';save();render()};if($('#resortMedia'))$('#resortMedia').onclick=()=>mediaDialog('resort');if($('#resortAddAudio'))$('#resortAddAudio').onclick=()=>mediaDialog('resort');if($('#resortPlay'))$('#resortPlay').onclick=startResortAudio;if($('#loungePlay'))$('#loungePlay').onclick=()=>{if(LOUNGE.on)LOUNGE.stop();else LOUNGE.start();$('#loungePlay').textContent=LOUNGE.on?'Pause the lounge set':'Start the lounge set'};if($('#loungeStyle'))$('#loungeStyle').onchange=e=>pianoStyle=e.target.value;if($('#recordedSong'))$('#recordedSong').onclick=()=>mediaDialog('piano');if($('#playNext'))$('#playNext').onclick=playNextRequest;document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>playTrack(b.dataset.track));if($('#pianoRequest'))$('#pianoRequest').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('request').trim(),track=prefs.pianoLibrary.find(t=>songKey(t.name)===songKey(name));prefs.pianoQueue.push({name,guest:prefs.name,track:track?.id,played:false});save();if(!track){let h=0;for(const c of name)h=(h*31+c.charCodeAt(0))%997;LOUNGE.seed=h||7;LOUNGE.start()}render();toast(track?'Recording added to the request queue.':'Request added as an improvisation mood; no exact recording is in your library.')};}
const renderStage3=function(){const keep=page===lastMediaPage?(page==='resort'&&prefs.resort===lastMediaResort?resortAudio:page==='piano'?pianoPlaying:null):null;if(keep)keep.remove();stopMedia(keep);prefs.fireworksMode='video';v2Render();if(page==='checkin'){$('#main').innerHTML=checkin();$('#breadcrumb').textContent='FAMILY CHECK-IN'}else if(page==='piano')$('#main').innerHTML=piano();if(!$('#familyCheckin')){const b=document.createElement('button');b.id='familyCheckin';b.textContent='Family check-in';document.querySelector('header>div').prepend(b)}bindExperience();if(keep){const mount=$(page==='resort'?'#resortAudioMount':'#pianoAudioMount');if(mount)mount.append(keep);else keep.pause()}lastMediaPage=page;lastMediaResort=prefs.resort;if(page==='terrace'){videoStarted=true;mountCinema()}if(page==='resort'&&prefs.resortMedia[prefs.resort]?.art?.startsWith('local:')){const epoch=mediaEpoch;mediaURL(prefs.resortMedia[prefs.resort].art).then(src=>{if(epoch===mediaEpoch&&$('#resortArt'))$('#resortArt').src=src}).catch(()=>toast('Choose the resort artwork again.'))}};
const settingsStage3=function(){return v2Settings().replace(/<select name="resort">[\s\S]*?<\/select>/,`<select name="resort">${resortChoices()}</select>`)};
const previousNavigate=navigateStage1;const navigateStage2=function(p){if(p!=='piano')LOUNGE.stop();previousNavigate(p)};
