/* connected.js */
/* Connected services: credentials remain on the Worker; family code is memory-only. */
let stationAccessCode='',chatHistory=[],connectedDestination='orlando';
async function servicePost(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Sparkle-Key':stationAccessCode},body:JSON.stringify(body),signal:AbortSignal.timeout(65000)});if(!r.ok){let d;try{d=await r.json()}catch{}throw Error(d?.error||'Service unavailable ('+r.status+')')}return r}
function connectedSetup(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<p class="eyebrow">CONNECTED FEATURES</p><h2>Your station’s connections</h2><p id="connectionStatus" role="status">Checking service configuration…</p><form id="accessForm"><label>Station access code<input type="password" id="stationCode" autocomplete="off" maxlength="200" required></label><p class="muted small">Use the code the owner configured in Cloudflare. This is not a Fish API key. Kept in memory until you reload.</p><button class="primary">Unlock for this session</button></form><details><summary>Owner setup</summary><p>In this Cloudflare Pages project, add a Workers AI binding named <code>AI</code>. Add secrets <code>SPARKLE_ACCESS_KEY</code> (a long random station code) and <code>FISH_API_KEY</code> (your Fish Audio API key). Redeploy. Optional variables: <code>AI_MODEL</code>, <code>FISH_MODEL</code>. See CONNECTED-SETUP.txt in the download.</p><p>Chat sends your question and recent conversation to Cloudflare AI. Generating a greeting sends the family name to Fish Audio. Provider usage may incur charges. No external requests occur until you ask or generate.</p></details><button id="setupClose">Close</button>`;d.showModal();$('#setupClose').onclick=()=>d.close();$('#accessForm').onsubmit=e=>{e.preventDefault();stationAccessCode=$('#stationCode').value;$('#stationCode').value='';toast('Code held for this session. It will be checked when you use a connected feature.');d.close()};const status=$('#connectionStatus');fetch('/api/features').then(r=>{if(!r.ok)throw Error();return r.json()}).then(f=>status.textContent=`Chat binding: ${f.chat?'configured':'missing'} · Fish key: ${f.voice?'configured':'missing'} · Family database: ${f.sync?'configured':'missing'} · Station protection: ${f.protected?'configured':'missing'}. Configuration presence does not verify account credits or provider access.`).catch(()=>status.textContent='Connection status unavailable. Confirm you deployed Revision 8 with its Worker.')}
const CHARACTER_VOICES=[['mickey','Mickey'],['classic','Classic Mickey'],['minnie','Minnie'],['goofy','Goofy'],['donald','Donald'],['pooh','Winnie the Pooh'],['tigger','Tigger']];
function installVoiceStudio(d){const host=document.createElement('section');host.className='card voice-studio';host.innerHTML=`<h3>A welcome just for your family</h3><p>Generate AI character speech for <strong>${esc(prefs.family)}</strong>. This sends the family name to Fish Audio. Generated speech is not an official Disney recording.</p><label>Character voice<select id="characterVoice">${CHARACTER_VOICES.map(([id,n])=>`<option value="${id}" ${prefs.welcomeVoice===id?'selected':''}>${n}</option>`).join('')}</select></label><div class="toolbar"><button id="generateWelcome">Generate personalized welcome</button><button id="voiceSetup">Connected features</button></div><p id="generatedStatus" role="status"></p><div id="generatedMount"></div>`;d.append(host);const status=host.querySelector('#generatedStatus'),mount=host.querySelector('#generatedMount'),btn=host.querySelector('#generateWelcome'),sel=host.querySelector('#characterVoice');let audio=null,url=null,closed=false;const close=d.onclose;d.onclose=()=>{closed=true;audio?.pause();if(url)URL.revokeObjectURL(url);d.querySelectorAll('audio').forEach(a=>a.pause());close?.()};const playSaved=async()=>{const saved=prefs.generatedGreeting;if(!saved)return;if(saved.family!==prefs.family||saved.voice!==sel.value){status.textContent='The saved greeting belongs to a different name or character. Generate a new one.';mount.innerHTML='';audio?.pause();return}try{const blob=await mediaDB('get',saved.key);if(closed||!blob)return;audio?.pause();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);mount.innerHTML='<audio controls></audio><p class="small">Saved AI greeting · plays without generating again.</p>';audio=mount.querySelector('audio');audio.src=url;audio.onplay=()=>{window.speechSynthesis?.cancel();d.querySelectorAll('audio').forEach(a=>{if(a!==audio)a.pause()})};audio.onerror=()=>status.textContent='The saved audio could not play. Try another character.'}catch{status.textContent='The saved audio is unavailable on this device.'}};sel.onchange=()=>{prefs.welcomeVoice=sel.value;save();playSaved()};host.querySelector('#voiceSetup').onclick=()=>{d.close();connectedSetup()};btn.onclick=async()=>{btn.disabled=true;status.textContent='Generating your greeting…';try{const family=prefs.family,voice=sel.value,r=await servicePost('/api/welcome',{family,voice}),blob=await r.blob();if(closed)return;if(blob.size>10*1024*1024)throw Error('Audio response too large');const key='local:'+crypto.randomUUID();await mediaDB('put',key,blob);prefs.generatedGreeting={family,voice,key};prefs.welcomeVoice=voice;save();await playSaved();status.textContent='Your greeting is ready. Press Play to hear it.'}catch(e){status.textContent=e.message}finally{btn.disabled=false}};playSaved()}


/* guide.js */
/* Discoverable help, a replayable tour, and a source-aware local park guide. */
const TOUR=[['Welcome to your happy place','Family check-in saves your family name, resort and trip date on this device.','checkin'],['Plan your next adventure','Plan your magic saves your itinerary. Crowds & planning opens park-specific historical data.','planner'],['Follow the parks','Choose a park on Park wait times. Missing readings mean unavailable, never automatically closed.','parks'],['A familiar voice','Family welcome includes a bundled Mickey voice sample. Personalized browser narration and your own recordings are separate choices.','home'],['Find a little magic','Look for a small three-circle Mickey on nine screens. Tap it to add it to your collection. Use Hint if you get stuck.','home'],['Settle in for the evening','Choose a fireworks recording, a resort soundtrack or the piano lounge. Media may need a tap to start.','terrace']];
function guideLink(url,label){return `<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`}
function guideAnswer(question){const q=question.toLowerCase();
 if(/weather|rain|temperature|forecast/.test(q))return 'weather';
 if(/ticket|price|cost|lightning/.test(q))return 'Ticket and Lightning Lane prices depend on the date and product. I do not have a live checkout quote. '+guideLink('https://disneyworld.disney.go.com/admission/','Walt Disney World ticket options')+' · '+guideLink('https://disneyland.disney.go.com/admission/','Disneyland ticket options');
 if(/wait|queue|ride|shortest/.test(q)){const rows=(live[selected]?.data||[]).filter(r=>r.entityType==='ATTRACTION'&&isFresh(r));const matches=rows.filter(r=>q.includes(r.name.toLowerCase()));const shown=matches.length?matches:rows.filter(r=>typeof waitValue(r)==='number').sort((a,b)=>waitValue(a)-waitValue(b)).slice(0,6);return `<strong>${esc(parkName())}</strong><br>${shown.length?shown.map(r=>esc(r.name)+': '+esc(waitValue(r))+(typeof waitValue(r)==='number'?' minutes':'')+' · '+esc(r.lastUpdated)).join('<br>'):'No matching fresh ride readings are loaded. Open Park wait times, select the park and press Refresh.'}<p>Source: ${esc(live[selected]?.source||'No connected reading')}. These are posted waits, not guarantees.</p>`}
 if(/best time|crowd|busy|when to go/.test(q))return 'Choose a park in Crowds & planning to compare its crowd calendar and historical wait statistics. Historical patterns are not a guarantee for your trip date. Tell the trip planner your dates and must-dos, and check operating hours before finalizing.';
 if(/hidden|hunt|mickey/.test(q))return `You have found ${prefs.hiddenMickeys.length} of ${HUNT_PAGES.length} hidden Mickeys. Use the Hint button in the magic toolbar to reveal the one on this screen. The Family welcome button plays the Mickey sample.`;
 if(/plan|trip|itinerary/.test(q))return 'Open Plan your magic from the toolbar. Add a date, destination, must-do and dining or rest notes. Save family reminders and download the plan. This notebook does not make bookings.';
 if(/music|piano|song/.test(q))return 'In the Piano Lounge, recorded requests need a matching recording in your library. The house songbook and lounge set use synthesized piano. In Resort channel, select a resort and press Play in its music player.';
 if(/cast|tv|video|firework/.test(q))return 'Use Fireworks terrace for recorded shows and Watch on TV for device instructions. TV mode changes the layout; use screen mirroring or Cast tab to show the whole app. A recorded show is not a live broadcast.';
 if(/resort|hotel/.test(q))return 'Open Resort channel and Browse resorts to search destinations, view photos and save favorites. Changing resorts selects its available theme and music suggestion.';
 return 'I’m a limited built-in guide, not a connected AI chatbot. I can help with app controls, loaded ride waits, Orlando weather, ticket-source links and planning tools. For detailed Disney questions, use '+guideLink('https://disneyworld.disney.go.com/faq/','Disney’s official help center')+'.';
}
async function guideWeather(){try{const r=await fetch('/api/weather/orlando',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const d=await r.json(),c=d.current;if(!c||!Number.isFinite(c.temperature_2m))throw Error();weatherHealth={at:Date.parse(c.time+'Z')-(d.utc_offset_seconds||0)*1000,error:false};return `Orlando / Walt Disney World area: ${esc(c.temperature_2m)}°F, feels like ${esc(c.apparent_temperature)}°F; wind ${esc(c.wind_speed_10m)} mph; precipitation ${esc(c.precipitation)} inches. Model time: ${esc(c.time)} (${esc(d.timezone)}). Source: ${guideLink('https://open-meteo.com/','Open-Meteo')} · modeled current conditions, not an on-site weather station.`}catch{weatherHealth.error=true;return 'Current weather is unavailable. '+guideLink('https://forecast.weather.gov/MapClick.php?lat=28.377&lon=-81.57','Open the National Weather Service forecast for Walt Disney World')}}
function openGuide(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<div class="sectionhead"><h2>Ask Mickey · Your Disney guide</h2><button id="closeGuide">Close</button></div><p class="muted">A fan-made guide. Connected AI can discuss Disney and build proposed itineraries; current facts require source data. Built-in help works without an AI connection.</p><div class="toolbar"><label>Mode<select id="guideMode"><option value="local">Built-in help</option><option value="ai">Conversational AI</option></select></label><label>Destination<select id="guideDestination">${[['orlando','Walt Disney World'],['anaheim','Disneyland California'],['paris','Disneyland Paris'],['tokyo','Tokyo Disney Resort'],['hongkong','Hong Kong Disneyland'],['shanghai','Shanghai Disney Resort']].map(([v,n])=>`<option value="${v}" ${v===connectedDestination?'selected':''}>${n}</option>`).join('')}</select></label><button id="guideSetup">Connected features</button><button id="clearChat">Clear conversation</button></div><p class="small">AI questions and recent conversation are sent to Cloudflare. Wait data uses the park selected on Park wait times; choose that park before asking. Built-in weather covers Orlando only.</p><div id="guideLog" role="log" aria-live="polite"></div><div class="toolbar">${['Current waits','Current weather','Ticket prices','Best time to go','Help plan a three-day trip'].map(t=>`<button data-guide-q="${t}">${t}</button>`).join('')}</div><form id="guideForm"><label>Your question<input id="guideQuestion" required maxlength="2000" placeholder="Ask about parks, your trip, or using the app…"></label><button class="primary" id="askSubmit">Ask</button></form><button id="saveChatPlan">Save last answer to trip reminders</button>`;d.showModal();$('#closeGuide').onclick=()=>d.close();$('#guideSetup').onclick=()=>{d.close();connectedSetup()};const log=$('#guideLog');let busy=false,lastAnswer='';const paint=()=>{log.innerHTML=chatHistory.map(m=>`<p><strong>${m.role==='user'?'You':'Guide'}:</strong> ${esc(m.content).replace(/\n/g,'<br>')}</p>`).join('')||'<p>Hi, pal! What would make your next Disney day special?</p>'};paint();$('#clearChat').onclick=()=>{chatHistory=[];lastAnswer='';paint()};$('#guideDestination').onchange=e=>{connectedDestination=e.target.value;chatHistory=[];paint()};$('#saveChatPlan').onclick=()=>{if(!lastAnswer)return toast('Ask a question first.');prefs.tripPlan.notes=(prefs.tripPlan.notes+'\n\nGuide draft (verify before travel):\n'+lastAnswer).trim().slice(0,5000);save();toast('Saved to trip reminders.')};const ask=async q=>{if(busy||!q.trim())return;busy=true;const mode=$('#guideMode').value,destination=$('#guideDestination').value,submit=$('#askSubmit');submit.disabled=true;const entry=document.createElement('div');entry.innerHTML=`<p><strong>You:</strong> ${esc(q)}</p><p class="guide-answer">Checking…</p>`;log.append(entry);const answer=entry.querySelector('.guide-answer');try{if(mode==='ai'){const qp=queuePark();const r=await servicePost('/api/chat',{question:q,destination,parkId:qp?.id,history:chatHistory.slice(-8)}),data=await r.json();lastAnswer=data.answer;answer.textContent=data.answer;answer.style.whiteSpace='pre-wrap';const refs=document.createElement('p');refs.className='small';refs.innerHTML=(data.sources||[]).filter(x=>/^https:\/\//.test(x.url)).map(x=>guideLink(x.url,x.label)).join(' · ')+' · Checked '+esc(data.checkedAt);entry.append(refs);chatHistory.push({role:'user',content:q},{role:'assistant',content:data.answer});chatHistory=chatHistory.slice(-16)}else{let a=guideAnswer(q);if(a==='weather')a=await guideWeather();answer.innerHTML=a;lastAnswer=answer.textContent}}catch(e){answer.textContent=e.message+' Choose Built-in help to continue without the service.'}finally{busy=false;submit.disabled=false}};$('#guideForm').onsubmit=e=>{e.preventDefault();ask($('#guideQuestion').value);$('#guideQuestion').value=''};d.querySelectorAll('[data-guide-q]').forEach(b=>b.onclick=()=>ask(b.dataset.guideQ))}
function openTour(step=0){const t=TOUR[step],d=$('#dialog');d.innerHTML=`<p class="eyebrow">YOUR SPARKLE TOUR · ${step+1} / ${TOUR.length}</p><h2>${t[0]}</h2><p>${t[1]}</p><div class="toolbar"><button id="tourVisit">Visit this screen</button><button id="tourNext" class="primary">${step===TOUR.length-1?'Finish tour':'Next'}</button><button id="tourClose">Close tour</button></div>`;if(!d.open)d.showModal();$('#tourClose').onclick=()=>d.close();$('#tourVisit').onclick=()=>{d.close();navigate(t[2])};$('#tourNext').onclick=()=>{if(step<TOUR.length-1)openTour(step+1);else{prefs.tourCompleted=true;save();d.close()}}}
function installGuide(){const main=$('#main');if(!main)return;const foot=$('footer>span');if(foot)foot.textContent=prefs.tagline+' · Revision 10';if(!$('#magicTools')){const bar=document.createElement('section');bar.id='magicTools';bar.className='magic-tools';bar.innerHTML=`<strong>Find your magic</strong><button data-magic="plan" title="Build and download your family itinerary">Plan your trip</button><button data-magic="tour" title="Six short steps to learn the app">Take the tour</button><button data-magic="guide" title="App help, loaded waits, weather and source links">Ask Mickey</button><button data-magic="hint" title="Reveal the hidden Mickey on this screen">Hidden Mickey hint</button><button data-magic="characters" title="Show or hide the character portrait strip">${prefs.showCharacters?'Hide':'Show'} friends</button><button data-magic="setup" title="Check AI and voice connections">Connected features</button><span>Revision 10</span>`;main.prepend(bar);bar.querySelectorAll('[data-magic]').forEach(b=>b.onclick=()=>{switch(b.dataset.magic){case'setup':connectedSetup();break;case'plan':navigate('planner');break;case'tour':openTour();break;case'guide':openGuide();break;case'characters':prefs.showCharacters=!prefs.showCharacters;save();render();break;case'hint':{const m=$('#hiddenMickey');if(m){m.classList.add('hinted');m.scrollIntoView({behavior:'smooth',block:'center'});m.focus();toast('Look for the glowing three-circle silhouette. Tap to collect it!')}else toast('Visit Home, Parks, Resort, Terrace, Multiview, Piano, Countdown, Planner or Settings to hunt.')}}})}}


