prefs.remoteNav ??= true;prefs.ambientMinutes ??= 0;prefs.rideAlerts ||= {};prefs.greetingPeople ||= [];prefs.booking ||= {eligibleHotel:true,dvc:true,visitDate:'',ticketDate:'',checkinReminder:''};
