let weatherHealth={at:0,error:false},lastInteraction=Date.now(),ambientDialog=null,ambientTimer=null,ambientURLs=[],syncRevision=null,syncBaseline='',syncAuto=false;
const SHARED_FIELDS=['family','resort','date','favorites','tripPlan','booking','googleAlbum','rideAlerts'];
function sharedState(){return Object.fromEntries(SHARED_FIELDS.map(k=>[k,prefs[k]??null]))}
function utcDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s||'')?new Date(s+'T12:00:00Z'):null}
function shiftDays(s,n){const d=utcDate(s);if(!d||isNaN(d))return '';d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
function shiftMonths(s,n){const d=utcDate(s);if(!d||isNaN(d))return '';const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+n);const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return d.toISOString().slice(0,10)}
function planningWindows(){const b=prefs.booking,date=prefs.date,visit=b.visitDate||date,ll=b.eligibleHotel?date:b.ticketDate||visit;return [{name:'Dining reservations',date:shiftDays(b.eligibleHotel?date:visit,-60),time:'06:00',note:b.eligibleHotel?'Eligible resort stay: up to 10 nights. Verify restaurant availability.':'Per dining date; change the visit date for another day.',url:'https://disneyworld.disney.go.com/dining/'},{name:'Lightning Lane purchase window',date:shiftDays(ll,b.eligibleHotel?-7:-3),time:'07:00',note:b.eligibleHotel?'Eligible hotel guests: 7 days before stay, up to 14 days.':'3 days before date-based ticket start, or park visit for other tickets/APs.',url:'https://disneyworld.disney.go.com/lightning-lane-passes/'},{name:'Online check-in reminder',date:b.checkinReminder||shiftDays(date,-60),time:'09:00',note:'Personal reminder, not an opening date. Check-in may be available as soon as the reservation is linked.',url:'https://disneyworld.disney.go.com/guest-services/online-resort-check-in/'},...(b.dvc?[{name:'DVC home-resort booking',date:shiftMonths(date,-11),time:'08:00',note:'Home-resort points, subject to membership eligibility and availability.',url:'https://disneyvacationclub.disney.go.com/'},{name:'DVC other-resort booking',date:shiftMonths(date,-7),time:'08:00',note:'Subject to membership restrictions and availability.',url:'https://disneyvacationclub.disney.go.com/'}]:[])].filter(x=>x.date)}
function downloadText(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function calendarExport(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Disney Sparkle//Family Planning//EN'];const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');for(const [i,w]of planningWindows().entries()){const dt=w.date.replaceAll('-','')+'T'+w.time.replace(':','')+'00';lines.push('BEGIN:VEVENT','UID:sparkle-'+w.date+'-'+i+'@family.local','DTSTAMP:'+stamp,'DTSTART;TZID=America/New_York:'+dt,'SUMMARY:'+w.name,'DESCRIPTION:Verify current eligibility and terms before booking.','URL:'+w.url,'BEGIN:VALARM','TRIGGER:-PT15M','ACTION:DISPLAY','DESCRIPTION:'+w.name,'END:VALARM','END:VEVENT')}lines.push('END:VCALENDAR');return lines.join('\r\n')}
function windowsMarkup(){return `<section class="card" id="planningWindows"><h2>Your Walt Disney World planning windows</h2><p>Dates are based on your saved arrival and the choices below. Times are Eastern. Calendar reminders work after importing them into your calendar; this page does not send background reminders.</p><form id="bookingForm" class="formgrid"><label><input name="eligibleHotel" type="checkbox" ${prefs.booking.eligibleHotel?'checked':''}> Eligible Disney/select hotel guest</label><label><input name="dvc" type="checkbox" ${prefs.booking.dvc?'checked':''}> Show DVC booking windows</label><label>Park visit / dining date<input name="visitDate" type="date" value="${esc(prefs.booking.visitDate)}"></label><label>Date-based ticket start (if applicable)<input name="ticketDate" type="date" value="${esc(prefs.booking.ticketDate)}"></label><label>My online check-in reminder date<input name="checkinReminder" type="date" value="${esc(prefs.booking.checkinReminder)}"></label><button>Update planning windows</button></form><div class="trip-days">${planningWindows().map(w=>`<article><h3>${w.name}</h3><strong>${w.date} · ${w.time} ET</strong><p>${w.note}</p>${guideLink(w.url,'Official details')}</article>`).join('')||'<p>Save an arrival date in Family check-in to see your windows.</p>'}</div><button id="exportWindows">Download calendar reminders (.ics)</button><p class="small">Rules checked November 6, 2026. These are WDW/DVC planning aids, not a guarantee of booking eligibility or availability.</p></section>`}
function feedLevel(at,limit,error=false){if(!at)return 'unavailable';return error||Date.now()-at>limit?'stale':'live'}
function healthMarkup(){const rows=(live[selected]?.data||[]).filter(r=>r.entityType==='ATTRACTION'),fresh=rows.filter(r=>isFresh(r)).length,wait=fresh?(errors[selected]?'stale':'live'):rows.length?'stale':'unavailable';const shows=getItems().filter(r=>r.entityType==='SHOW'&&r.showtimes?.length),show=shows.length?(shows.every(isFresh)?'live':'stale'):'unavailable';return `<span class="health-item ${wait}">● Waits: ${wait}${fresh?' ('+fresh+')':''}</span><span class="health-item ${show}">● Showtimes: ${show}</span><span class="health-item ${feedLevel(weatherHealth.at,900000,weatherHealth.error)}">● Weather: ${feedLevel(weatherHealth.at,900000,weatherHealth.error)}</span><span>${navigator.onLine?'Network connected':'Offline · saved content'}</span>`}
function sampleWaits(id){const rows=live[id]?.data||[];const now=Date.now();for(const r of rows){if(r.entityType!=='ATTRACTION'||!isFresh(r)||r.status!=='OPERATING'||!Number.isFinite(r.queue?.STANDBY?.waitTime))continue;const key=id+'|'+r.id,t=Date.parse(r.lastUpdated),list=(waitHistory[key]||[]).filter(p=>now-p.t<21600000);if(!list.some(p=>p.t===t))list.push({t,w:r.queue.STANDBY.waitTime});waitHistory[key]=list.sort((a,b)=>a.t-b.t).slice(-120);const alert=prefs.rideAlerts[r.id];if(alert&&prefs.favorites.includes(r.id)){const under=r.queue.STANDBY.waitTime<alert.threshold;if(under&&!alert.wasUnder){alert.wasUnder=true;const msg=r.name+' is now '+r.queue.STANDBY.waitTime+' minutes (under '+alert.threshold+').';toast(msg);if(typeof Notification!=='undefined'&&Notification.permission==='granted')try{new Notification('Disney Sparkle ride alert',{body:msg,tag:r.id})}catch{}}else if(!under)alert.wasUnder=false}}
 for(const k of Object.keys(waitHistory)){waitHistory[k]=waitHistory[k].filter(p=>now-p.t<21600000);if(!waitHistory[k].length)delete waitHistory[k]}
 try{localStorage.setItem('sparkle.waitHistory',JSON.stringify(waitHistory));localStorage.setItem('sparkle.lastFeeds',JSON.stringify({live,schedules,parks,queueParks,selected,scheduleFetched}));save()}catch{}
}
function trendMarkup(id){const p=(waitHistory[selected+'|'+id]||[]).filter(x=>Date.now()-x.t<21600000);if(p.length<2)return '<small class="muted">Trend collecting · keep app open</small>';const min=Math.min(...p.map(x=>x.w)),max=Math.max(...p.map(x=>x.w)),span=p.at(-1).t-p[0].t||1,points=p.map(x=>((x.t-p[0].t)/span*100).toFixed(1)+','+(28-(x.w-min)/(max-min||1)*24).toFixed(1)).join(' '),delta=p.at(-1).w-p[0].w;return `<svg class="wait-trend" viewBox="0 0 104 32" role="img" aria-label="${delta>0?'Rising':delta<0?'Dropping':'Steady'} by ${Math.abs(delta)} minutes over ${Math.round(span/60000)} minutes"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2"/></svg><small>${delta>0?'Rising':delta<0?'Dropping':'Steady'} · ${p.length} readings · ${Math.round(span/60000)} min</small>`}
function rideAlertDialog(id,name){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>Alert for ${esc(name)}</h2><form id="rideAlertForm"><label>Tell me when the posted wait is under<input name="threshold" type="number" min="1" max="300" required value="${prefs.rideAlerts[id]?.threshold||45}"></label><button>Save alert & favorite</button></form><p>Checks fresh readings for the currently selected park while the app is open. Not a background push service. Re-alerts only after the wait rises above the threshold and drops again.</p><button id="enableNotices">Enable device notifications</button><button id="removeAlert">Remove alert</button><button id="closeAlert">Close</button>`;d.showModal();$('#closeAlert').onclick=()=>d.close();$('#removeAlert').onclick=()=>{delete prefs.rideAlerts[id];save();d.close()};$('#rideAlertForm').onsubmit=e=>{e.preventDefault();const n=Number(new FormData(e.target).get('threshold'));if(n<1||n>300)return;prefs.rideAlerts[id]={threshold:n,wasUnder:false};if(!prefs.favorites.includes(id))prefs.favorites.push(id);save();d.close();sampleWaits(selected);render()};$('#enableNotices').onclick=async()=>{if(typeof Notification==='undefined')return toast('Notifications unavailable in this browser. In-app alerts still work.');toast('Notification permission: '+await Notification.requestPermission())}}
function remoteCandidates(){const scope=document.querySelector('dialog[open]')||document;return [...scope.querySelectorAll('button,a[href],input,select,textarea,summary,[tabindex="0"]')].filter(e=>!e.disabled&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden')}
function handleRemote(e){if(!prefs.remoteNav&&!document.body.classList.contains('tv'))return;const active=document.activeElement;if(active?.isContentEditable)return;if(active?.tagName==='SELECT'&&['ArrowUp','ArrowDown'].includes(e.key))return;if((active?.tagName==='TEXTAREA'||(active?.tagName==='INPUT'&&!['checkbox','radio','button','submit'].includes(active.type)))&&['ArrowLeft','ArrowRight'].includes(e.key))return;if(e.key==='Enter'&&active?.tagName==='INPUT'&&['checkbox','radio'].includes(active.type)){e.preventDefault();active.click();return;}if(['Escape','Backspace','BrowserBack'].includes(e.key)){if(document.querySelector('dialog[open]')){e.preventDefault();document.querySelector('dialog[open]').close()}else if(page!=='home'){e.preventDefault();navigate('home')}return}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const all=remoteCandidates();if(!all.length)return;e.preventDefault();if(!all.includes(active)){all[0].focus();return}const r=active.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2,vertical=/Up|Down/.test(e.key),sign=/Down|Right/.test(e.key)?1:-1;let best=null,score=Infinity;for(const el of all){if(el===active)continue;const q=el.getBoundingClientRect(),dx=q.x+q.width/2-x,dy=q.y+q.height/2-y,forward=(vertical?dy:dx)*sign,cross=Math.abs(vertical?dx:dy);if(forward<=2)continue;const s=forward+cross*3;if(s<score){best=el;score=s}}if(best){best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'})}}
async function startAmbient(){if(ambientDialog)return;const d=document.createElement('dialog');d.id='ambientDisplay';d.setAttribute('aria-label','Ambient family display. Press any key to wake.');d.innerHTML='<div id="ambientContent"></div><p class="ambient-wake">Press any key or tap to return</p>';document.body.append(d);ambientDialog=d;d.showModal();const photos=await photoStore('get').catch(()=>[]);if(ambientDialog!==d)return;ambientURLs=photos.map(p=>URL.createObjectURL(p.blob));let i=0;const show=()=>{if(!ambientDialog)return;const slot=i++%(ambientURLs.length+2),target=$('#ambientContent');if(slot<ambientURLs.length)target.innerHTML=`<img src="${ambientURLs[slot]}" alt="Family vacation memory">`;else if(slot===ambientURLs.length)target.innerHTML=`<p class="eyebrow">${esc(prefs.family)}</p><h1>${days()===null?'Your next adventure awaits':days()+' days to the magic'}</h1><p>${esc(prefs.resort)}</p>`;else{const now=Date.now(),shows=getItems().filter(s=>s.entityType==='SHOW'&&isFresh(s)).flatMap(s=>(s.showtimes||[]).filter(t=>Date.parse(t.startTime)>=now&&Date.parse(t.startTime)<now+12*3600000).map(t=>esc(s.name)+' · '+time(t.startTime)));target.innerHTML=`<p class="eyebrow">${esc(parkName())}</p><h1>Coming up on stage</h1><p>${shows.join('<br>')||'Fresh upcoming showtimes unavailable'}</p><p class="small">Published schedule · not a live broadcast</p>`}};show();ambientTimer=setInterval(show,20000);d.onclose=stopAmbient}
function stopAmbient(){const d=ambientDialog;if(!d)return;ambientDialog=null;clearInterval(ambientTimer);ambientURLs.forEach(URL.revokeObjectURL);ambientURLs=[];d.remove();lastInteraction=Date.now()}
function wakeAmbient(e){lastInteraction=Date.now();if(ambientDialog){e.preventDefault();e.stopImmediatePropagation();stopAmbient()}}
function stationOptions(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>Make the TV feel like home</h2><form id="stationOptions"><label><input type="checkbox" name="remote" ${prefs.remoteNav?'checked':''}> Arrow-key remote navigation</label><label>Start ambient display after<select name="idle">${[[0,'Never automatically'],[2,'2 idle minutes'],[5,'5 idle minutes'],[10,'10 idle minutes']].map(([n,t])=>`<option value="${n}" ${prefs.ambientMinutes===n?'selected':''}>${t}</option>`).join('')}</select></label><button>Save display choices</button></form><p>Ambient mode rotates photos, countdown and fresh upcoming showtimes. It stays off while a dialog is open or on Terrace, Multiview or Piano. Press any key or tap to wake. Arrow keys move focus; OK/Enter activates. In text fields, Up/Down moves focus and Left/Right edits. In dropdowns, Up/Down chooses and Left/Right moves focus.</p><button id="startAmbient">Start ambient display now</button><button id="stationClose">Close</button>`;d.showModal();$('#stationClose').onclick=()=>d.close();$('#startAmbient').onclick=()=>{d.close();startAmbient()};$('#stationOptions').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);prefs.remoteNav=f.has('remote');prefs.ambientMinutes=Number(f.get('idle'));save();d.close()}}
function greetingRecorder(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>A familiar voice from home</h2><p>Record up to 30 seconds on this device. Your microphone starts only when you press Record and allow access. Recordings stay on this device; use Download to transfer one to another device’s Family Welcome upload.</p><label>Who is welcoming you?<input id="greetingPerson" maxlength="80" placeholder="Tammy"></label><div class="toolbar"><button id="recordGreeting">Record</button><button id="stopRecording" disabled>Stop & save</button></div><p id="recordStatus" role="status"></p><label>Play a family greeting<select id="personGreeting"><option value="">Choose a person…</option>${prefs.greetingPeople.map(p=>`<option value="${esc(p.key)}">${esc(p.name)}</option>`).join('')}</select></label><audio id="personAudio" controls></audio><a id="downloadGreeting" hidden download="family-greeting.webm">Download recording</a><button id="recordClose">Close</button>`;d.showModal();let recorder,stream,timer,url,closed=false;const status=$('#recordStatus'),audio=$('#personAudio'),list=$('#personGreeting'),start=$('#recordGreeting'),stop=$('#stopRecording'),person=$('#greetingPerson');const clean=()=>{closed=true;clearTimeout(timer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());audio.pause();if(url)URL.revokeObjectURL(url)};d.onclose=clean;$('#recordClose').onclick=()=>{clean();d.close()};list.onchange=async()=>{audio.pause();if(url)URL.revokeObjectURL(url);if(!list.value)return;try{const blob=await mediaDB('get',list.value);if(closed||!blob)return;url=URL.createObjectURL(blob);audio.src=url;const link=$('#downloadGreeting');link.href=url;link.hidden=false;link.download='family-greeting.'+(blob.type.includes('mp4')?'m4a':'webm');audio.play().catch(()=>status.textContent='Press Play to hear this greeting.')}catch{status.textContent='Recording unavailable on this device.'}};start.onclick=async()=>{if(!person.value.trim())return status.textContent='Enter the person’s name first.';if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined')return status.textContent='Recording is unavailable. Use Family Welcome to upload an audio file.';start.disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(closed){stream.getTracks().forEach(t=>t.stop());return}const chunks=[],name=person.value.trim();recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());stop.disabled=true;start.disabled=false;if(closed)return;try{const blob=new Blob(chunks,{type:recorder.mimeType}),key='local:'+crypto.randomUUID();await mediaDB('put',key,blob);prefs.greetingPeople.push({name,key});save();const o=document.createElement('option');o.value=key;o.textContent=name;list.append(o);list.value=key;status.textContent='Greeting saved. Choose a name to hear it.';list.onchange()}catch{status.textContent='Unable to save recording.'}};recorder.start();stop.disabled=false;status.textContent='Recording… maximum 30 seconds';timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop()},30000)}catch{stream?.getTracks().forEach(t=>t.stop());start.disabled=false;status.textContent='Microphone unavailable or permission declined.'}};stop.onclick=()=>{if(recorder?.state==='recording')recorder.stop()}}
function installFamilyTools(){const main=$('#main');if(!main)return;const bar=$('#magicTools');if(bar&&!$('#familyTools')){const el=document.createElement('div');el.id='familyTools';el.className='toolbar';el.innerHTML='<button id="displayOptions">TV & ambient</button><button id="familyVoices">Family voices</button><button id="familySync">Family sync</button><button id="googlePhotos">Google Photos album</button>';bar.after(el);$('#displayOptions').onclick=stationOptions;$('#familyVoices').onclick=greetingRecorder;$('#familySync').onclick=syncDialog;$('#googlePhotos').onclick=googlePhotosDialog}if(!$('#feedHealth')){const h=document.createElement('div');h.id='feedHealth';h.className='feed-health';h.setAttribute('role','status');main.prepend(h)}$('#feedHealth').innerHTML=healthMarkup();if(['planner','vacation'].includes(page)&&!$('#planningWindows')){const el=document.createElement('div');el.innerHTML=windowsMarkup();main.append(el);$('#bookingForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);prefs.booking={eligibleHotel:f.has('eligibleHotel'),dvc:f.has('dvc'),visitDate:f.get('visitDate'),ticketDate:f.get('ticketDate'),checkinReminder:f.get('checkinReminder')};save();render()};$('#exportWindows').onclick=()=>downloadText('disney-planning-windows.ics',calendarExport(),'text/calendar')}if(page==='parks')document.querySelectorAll('[data-favorite]').forEach(b=>{const card=b.closest('.ride');if(!card||card.querySelector('.ride-extra'))return;const r=getItems().find(x=>x.id===b.dataset.favorite);if(!r)return;const el=document.createElement('div');el.className='ride-extra';el.innerHTML=trendMarkup(r.id)+`<button aria-label="Set wait alert for ${esc(r.name)}">${prefs.rideAlerts[r.id]?'Edit':'Set'} wait alert</button>`;el.querySelector('button').onclick=()=>rideAlertDialog(r.id,r.name);card.append(el)});installTripTools()}
function googlePhotosDialog(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>Your shared Google Photos album</h2><p>Keep the family album one tap away. A shared link opens Google Photos; it does not grant this app permission to read or continuously sync its contents.</p><form id="albumForm"><label>Shared album link<input name="url" type="url" value="${esc(prefs.googleAlbum||'')}" placeholder="https://photos.app.goo.gl/…" required></label><button>Save album shortcut</button></form><div id="albumLink">${prefs.googleAlbum?guideLink(prefs.googleAlbum,'Open family album'):''}</div><p>For the ambient slideshow, download selected photos from your album and add them together under Your memories. Google’s current Picker API requires Google Cloud OAuth setup and explicit selection; automatic shared-album ingestion is not included.</p><button id="albumClose">Close</button>`;d.showModal();$('#albumClose').onclick=()=>d.close();$('#albumForm').onsubmit=e=>{e.preventDefault();try{const u=new URL(new FormData(e.target).get('url'));if(u.protocol!=='https:'||!['photos.app.goo.gl','photos.google.com'].includes(u.hostname))throw Error();prefs.googleAlbum=u.href;save();$('#albumLink').innerHTML=guideLink(u.href,'Open family album');toast('Album shortcut saved.')}catch{toast('Use a Google Photos HTTPS shared link.')}}}
function bootFamilyTools(){let lastTripDay=tripToday();setInterval(()=>{if(page==='home'&&!document.hidden&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){const changed=lastTripDay!==tripToday();lastTripDay=tripToday();if(changed){tripHomeOverride=false;alignTripPark();loadPark(true)}if(tripIsActive()||changed)render()}},60000);try{const c=JSON.parse(localStorage.getItem('sparkle.lastFeeds')||'null');if(c&&Array.isArray(c.parks)){parks=c.parks;live=c.live||{};schedules=c.schedules||{};selected=c.selected||selected;scheduleFetched=c.scheduleFetched||{};queueParks=c.queueParks||[]}}catch{}document.addEventListener('keydown',wakeAmbient,true);document.addEventListener('pointerdown',wakeAmbient,true);document.addEventListener('keydown',handleRemote);document.addEventListener('pointermove',()=>lastInteraction=Date.now());document.addEventListener('input',()=>lastInteraction=Date.now());setInterval(()=>{if($('#feedHealth'))$('#feedHealth').innerHTML=healthMarkup();if(prefs.ambientMinutes&&!ambientDialog&&!document.hidden&&!document.querySelector('dialog[open]')&&!['terrace','piano','multiview'].includes(page)&&Date.now()-lastInteraction>prefs.ambientMinutes*60000)startAmbient()},15000);if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('/sw.js').catch(()=>{});setInterval(()=>{if(syncAuto&&stationAccessCode&&!document.hidden&&!document.querySelector('dialog[open]'))syncPull(true).catch(()=>{})},60000)}
async function familyRequest(path,method='GET',body=null){const r=await fetch('/api/family'+path,{method,headers:{'X-Sparkle-Key':stationAccessCode,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!r.ok){let d;try{d=await r.json()}catch{}throw Error(d?.error||'Family sync unavailable ('+r.status+')')}return r}
function applyFamilyState(state){for(const k of SHARED_FIELDS)if(state[k]!==undefined&&state[k]!==null)prefs[k]=state[k];save()}
async function syncPull(auto=false){if(auto&&(!syncBaseline||JSON.stringify(sharedState())!==syncBaseline))return;const d=await(await familyRequest('/state')).json();if(!d.state){syncRevision=d.revision;syncBaseline=JSON.stringify(sharedState());return}if(auto&&d.revision===syncRevision)return;applyFamilyState(d.state);syncRevision=d.revision;syncBaseline=JSON.stringify(sharedState());if(auto){render();toast('Family settings updated from your shared station.')}}
async function syncPush(){if(syncRevision===null){const current=await(await familyRequest('/state')).json();if(current.revision!==0)throw Error('A shared family already exists. Load it first to avoid overwriting someone’s changes.');syncRevision=0}const d=await(await familyRequest('/state','POST',{revision:syncRevision,state:sharedState()})).json();syncRevision=d.revision;syncBaseline=JSON.stringify(sharedState())}
async function jpegForSharing(blob){const bitmap=await createImageBitmap(blob);try{const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const result=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.75));if(!result||result.size>1000000)throw Error('Photo is too large after resizing. Use a smaller image.');return result}finally{bitmap.close()}}
async function syncPhotosUpload(){const photos=await photoStore('get');if(photos.length>20)throw Error('Share up to 20 photos at a time. Remove extra local photos or use a smaller collection.');let count=0;for(const p of photos){const id=p.id.replace(/^shared-/,'');if(!/^[a-f0-9-]{36}$/.test(id))continue;const blob=await jpegForSharing(p.blob);const r=await fetch('/api/family/photo/'+id+'?name='+encodeURIComponent(p.name.slice(0,100)),{method:'PUT',headers:{'X-Sparkle-Key':stationAccessCode,'Content-Type':'image/jpeg'},body:blob});if(!r.ok){const d=await r.json();throw Error(d.error||'Photo upload failed')}count++}return count}
async function syncPhotosDownload(){const list=await(await familyRequest('/photos')).json();let count=0;for(const p of list.photos){const blob=await(await familyRequest('/photo/'+p.id)).blob();await photoStore('put',{id:p.id,name:p.name,blob});count++}return count}
function syncDialog(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>Our family, on every screen</h2><p>Share this station’s family name, resort, countdown, favorite rides, alert thresholds, planning notes, trip dates, dining entries, DVC snapshots and Google Photos shortcut. Your device’s station title, voice recordings and playback settings stay local.</p><p id="syncStatus" role="status">${stationAccessCode?'Station code entered for this session.':'First enter your station code in Connected features.'}</p><div class="toolbar"><button id="syncPull">Load shared settings onto this device</button><button id="syncPush">Save this device’s settings to family</button><button id="syncConfigure">Connected features</button></div><label><input id="syncAuto" type="checkbox" ${syncAuto?'checked':''}> Check for shared changes every minute this session</label><p class="small">Loading replaces the shared fields on this device. Automatic checks pause if this device has unsaved local changes. Conflicting saves are rejected; load the latest family state before retrying.</p><h3>Shared photo collection</h3><p>Up to 20 JPEG photos, resized to 1600 pixels and under 1 MB each. Downloads merge into this device’s memory wall. Remove a shared photo below to make room; local copies are retained. No Google album crawling.</p><div class="toolbar"><button id="photoPush">Upload local photos to family</button><button id="photoPull">Download family photos</button><button id="photoManage">Manage shared photos</button></div><div id="sharedPhotoList"></div><p class="small">Requires a Cloudflare D1 binding named FAMILY_DB and the included schema. This is one private family collection per deployment. Recordings remain local; download and transfer them if needed.</p><button id="syncClose">Close</button>`;d.showModal();const status=$('#syncStatus');const run=async fn=>{d.querySelectorAll('button').forEach(b=>b.disabled=true);try{status.textContent='Syncing…';status.textContent=await fn()}catch(e){status.textContent=e.message}finally{d.querySelectorAll('button').forEach(b=>b.disabled=false)}};$('#syncClose').onclick=()=>{d.close();render()};$('#syncConfigure').onclick=()=>{d.close();connectedSetup()};$('#syncAuto').onchange=e=>syncAuto=e.target.checked;$('#syncPull').onclick=()=>run(async()=>{await syncPull();return 'Shared settings loaded. Close to see changes.'});$('#syncPush').onclick=()=>run(async()=>{await syncPush();return 'Family settings saved.'});$('#photoManage').onclick=()=>run(async()=>{const data=await(await familyRequest('/photos')).json();$('#sharedPhotoList').innerHTML=data.photos.map(p=>`<p>${esc(p.name)} <button data-remove-shared="${esc(p.id)}">Remove shared copy</button></p>`).join('')||'<p>No shared photos yet.</p>';$('#sharedPhotoList').querySelectorAll('[data-remove-shared]').forEach(b=>b.onclick=()=>run(async()=>{await familyRequest('/photo/'+b.dataset.removeShared,'DELETE');b.parentElement.remove();return 'Shared copy removed. Local photos are unchanged.'}));return 'Shared photo collection loaded.'});$('#photoPush').onclick=()=>run(async()=>`${await syncPhotosUpload()} photos uploaded.`);$('#photoPull').onclick=()=>run(async()=>`${await syncPhotosDownload()} photos downloaded. Open Your memories to see them.`)}


/* trip-day.js */
/* Trip-day dashboard, structured dining notebook, and manual DVC ledger. */
prefs.tripSettings ||= {end:'',mode:'auto',timezone:'America/New_York',parkByDate:{}};
prefs.tripSettings.parkByDate ||= {};prefs.dining ||= [];prefs.dvc ||= [];
SHARED_FIELDS.push('tripSettings','dining','dvc');
let tripHomeOverride=false;
function tripToday(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:prefs.tripSettings.timezone||'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
function tripIsActive(now=new Date()){const t=tripToday(now);return prefs.tripSettings.mode!=='off'&&!!prefs.date&&!!prefs.tripSettings.end&&t>=prefs.date&&t<=prefs.tripSettings.end}
function tripParkId(){return prefs.tripSettings.parkByDate?.[tripToday()]||''}
function alignTripPark(){const id=tripParkId();if(tripIsActive()&&id&&parks.some(p=>p.id===id)&&selected!==id)selected=id}
function upcomingTripShows(now=Date.now()){return getItems().filter(r=>r.entityType==='SHOW'&&isFresh(r)).flatMap(r=>(r.showtimes||[]).filter(t=>Date.parse(t.startTime)>=now&&tripToday(new Date(t.startTime))===tripToday(new Date(now))).map(t=>({name:r.name,start:t.startTime}))).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).slice(0,3)}
function tripDashboard(){const today=tripToday(),rows=getItems().filter(r=>r.entityType==='ATTRACTION'&&prefs.favorites.includes(r.id)),shows=upcomingTripShows(),hours=(schedules[selected]||[]).filter(s=>s.type==='OPERATING'&&s.date===today),dining=prefs.dining.filter(r=>r.date===today).sort((a,b)=>a.time.localeCompare(b.time)),notes=prefs.tripPlan.days.filter(d=>d.date===today);return title('Today is your Disney day.',`${esc(prefs.family)} · ${esc(today)} · ${esc(parkName())}`,'YOUR MAGIC, RIGHT NOW')+`<section class="card trip-day-banner"><p class="eyebrow">TRIP-DAY MODE</p><h2>Less searching. More being here.</h2><p>Today’s selected park: <strong>${esc(parkName())}</strong>. ${tripParkId()?'Saved for this date.':'Choose today’s park below; notebook text is not automatically treated as a park selection.'}</p><div class="toolbar"><select id="tripDayPark" aria-label="Today’s park">${parkOptions()}</select><button id="saveTripDayPark">Use this park today</button><button id="dreamHome">Show my at-home welcome</button></div></section><div class="trip-days"><section class="card"><p class="eyebrow">TODAY’S PARK HOURS</p><h2>${hours.map(s=>time(s.openingTime)+' – '+time(s.closingTime)).join('<br>')||'Hours unavailable'}</h2><p>Published operating schedule · ${scheduleFetched[selected]&&Date.now()-scheduleFetched[selected]<900000?'recently refreshed':'saved / refresh unavailable'} · verify changes in the official app.</p></section><section class="card"><p class="eyebrow">NEXT THREE SHOWTIMES</p>${shows.map(s=>`<p><strong>${time(s.start)}</strong> · ${esc(s.name)}</p>`).join('')||'<p>No fresh upcoming showtimes available.</p>'}</section><section class="card"><p class="eyebrow">YOUR STARRED RIDES</p>${rows.map(r=>`<p><strong>${esc(r.name)}</strong> · ${isFresh(r)&&r.status==='OPERATING'&&Number.isFinite(r.queue?.STANDBY?.waitTime)?r.queue.STANDBY.waitTime+' min':isFresh(r)?esc((r.status||'Unknown').replaceAll('_',' ')):'Reading stale / unavailable'}</p>`).join('')||'<p>Star rides in this park to see them here.</p>'}<button data-page="parks">See all rides</button></section><section class="card"><p class="eyebrow">TODAY’S DINING NOTEBOOK</p>${dining.map(r=>`<p><strong>${esc(r.time)} · ${esc(r.name)}</strong><br>${esc(r.location)} · ${esc(r.status)}</p>`).join('')||'<p>No timed dining entries for today.</p>'}${notes.map(d=>`<p><strong>${esc(d.park)}</strong><br>${esc(d.priority)}<br>${esc(d.notes)}</p>`).join('')}<button data-page="planner">Edit dining & plans</button><p class="small">Your entries, not a reservation-system connection.</p></section></div>`}
const tripPreviousHome=homeStage3;
const homeStage4=function(){alignTripPark();return tripIsActive()&&!tripHomeOverride?tripDashboard():tripPreviousHome()};
function tripConfigMarkup(){return `<section class="card" id="tripSettingsCard"><h2>Bring your happy place into the parks.</h2><form id="tripSettingsForm" class="formgrid"><label>Arrival date<input name="start" type="date" required value="${esc(prefs.date)}"></label><label>Last trip day (included)<input name="end" type="date" required value="${esc(prefs.tripSettings.end)}"></label><label>Trip time zone<select name="timezone">${[['America/New_York','Orlando / Eastern'],['America/Los_Angeles','Anaheim / Pacific'],['Europe/Paris','Paris'],['Asia/Tokyo','Tokyo'],['Asia/Hong_Kong','Hong Kong'],['Asia/Shanghai','Shanghai']].map(([v,n])=>`<option value="${v}" ${prefs.tripSettings.timezone===v?'selected':''}>${n}</option>`).join('')}</select></label><label><input name="auto" type="checkbox" ${prefs.tripSettings.mode!=='off'?'checked':''}> Automatically show trip-day Home during these dates</label><button>Save trip-day settings</button></form><p>Arrival through last day, inclusive, in the trip’s time zone. Home shows your selected park. Use Home’s park picker each day to save that date’s park.</p></section>`}
function diningMarkup(){return `<section class="card" id="diningNotebook"><h2>A table worth looking forward to.</h2><form id="diningForm" class="formgrid"><label>Dining date<input name="date" type="date" required value="${esc(prefs.date)}"></label><label>Local time<input name="time" type="time" required></label><label>Restaurant<input name="name" required maxlength="100"></label><label>Location / resort<input name="location" maxlength="100"></label><label>Status<select name="status"><option>Planned · not booked</option><option>Confirmed by family</option></select></label><button>Add dining entry</button></form>${prefs.dining.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(r=>`<article><p><strong>${esc(r.date)} · ${esc(r.time)} · ${esc(r.name)}</strong><br>${esc(r.location)} · ${esc(r.status)}</p><button data-dining-remove="${esc(r.id)}">Remove dining entry</button></article>`).join('')}<p>No booking is made here. Existing free-text dining notes also appear on the matching trip day.</p></section>`}
function dvcDates(c){const start=c.year+'-'+String(c.month).padStart(2,'0')+'-01';return {start,bank:shiftDays(shiftMonths(start,8),-1),expires:shiftDays(shiftMonths(start,12),-1)}}
function dvcBalance(c){return Number(c.current||0)+Number(c.banked||0)+Number(c.borrowed||0)}
function dvcMarkup(){return `<section class="card" id="dvcTracker"><p class="eyebrow">YOUR NEXT CHAPTER OF MAGIC</p><h2>Your DVC points, with a little perspective.</h2><p>Enter remaining, uncommitted balances from your DVC dashboard—not annual allotments. This manual tracker does not connect to Disney or move points. Separate contracts and Use Years stay separate.</p><form id="dvcForm" class="formgrid"><label>Contract / home resort nickname<input name="name" required maxlength="80" placeholder="Our Polynesian points"></label><label>Use Year starts in<select name="month">${[2,3,4,6,8,9,10,12].map(m=>`<option value="${m}">${new Intl.DateTimeFormat('en-US',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,m-1,1)))}</option>`).join('')}</select></label><label>Use Year starting year<input name="year" type="number" min="2020" max="2100" value="${new Date().getFullYear()}" required></label>${[['current','Current-year points remaining'],['banked','Banked points remaining'],['borrowed','Borrowed points remaining']].map(([k,n])=>`<label>${n}<input name="${k}" type="number" min="0" max="100000" step="1" value="0" required></label>`).join('')}<label>Borrowing decision reminder (optional)<input name="borrowReminder" type="date"></label><button>Save contract snapshot</button></form><div class="trip-days">${prefs.dvc.map(c=>{const d=dvcDates(c),today=tripToday();return `<article class="card"><h3>${esc(c.name)} · ${c.year} Use Year</h3><h2>${dvcBalance(c)} points remaining</h2><p>${c.current} current · ${c.banked} banked · ${c.borrowed} borrowed</p><p><strong>Bank by ${d.bank}</strong>${today>d.bank?' · deadline passed':''}<br>Only eligible current-year points; banked/borrowed points cannot be banked again.</p><p><strong>Use-Year expiration: ${d.expires}</strong>${today>d.expires?' · expired snapshot, update your ledger':''}<br>Banked/borrowed points must be used within the Use Year into which they were moved.</p><p>Borrowing occurs when making a reservation; there is no fixed annual borrowing deadline.${c.borrowReminder?' Your decision reminder: '+esc(c.borrowReminder):''}</p><p class="small">Manual snapshot saved ${esc(c.updated)}. Restricted/holding points need separate verification with DVC.</p><button data-dvc-edit="${esc(c.id)}">Edit snapshot</button><button data-dvc-remove="${esc(c.id)}">Remove snapshot</button></article>`}).join('')}</div><button id="dvcCalendar">Download DVC calendar reminders</button><p>Calendar events include 30-day and 7-day advance reminders. Import them into your calendar. No automatic point banking, borrowing or yearly rollover.</p><a href="https://disneyvacationclub.disney.go.com/faq/points" target="_blank" rel="noopener">Verify your points and current DVC rules ↗</a></section>`}
function dvcCalendar(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Disney Sparkle//DVC//EN'];for(const c of prefs.dvc){const d=dvcDates(c);for(const [key,date,label]of [['bank',d.bank,'DVC banking deadline'],['expires',d.expires,'DVC Use Year expires'],['borrow',c.borrowReminder,'DVC borrowing decision reminder']]){if(!date)continue;lines.push('BEGIN:VEVENT',`UID:dvc-${c.id}-${c.year}-${key}@sparkle.local`,'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART;VALUE=DATE:'+date.replaceAll('-',''),'SUMMARY:'+label,'DESCRIPTION:Check your manual points snapshot against your official DVC account.');for(const days of [30,7])lines.push('BEGIN:VALARM',`TRIGGER:-P${days}D`,'ACTION:DISPLAY','DESCRIPTION:'+label,'END:VALARM');lines.push('END:VEVENT')}}lines.push('END:VCALENDAR');return lines.join('\r\n')}
function installTripTools(){const bar=$('#familyTools');if(bar&&!$('#pocketAlerts')){const b=document.createElement('button');b.id='pocketAlerts';b.textContent='Pocket ride alerts';b.onclick=pushDialog;bar.append(b)}if(['planner','vacation'].includes(page)&&!$('#tripSettingsCard')){const box=document.createElement('div');box.className='trip-tools';box.innerHTML=tripConfigMarkup()+(page==='planner'?diningMarkup():'')+dvcMarkup();$('#main').append(box);$('#tripSettingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),start=f.get('start'),end=f.get('end');if(end<start)return toast('Last trip day must be on or after arrival.');prefs.date=start;Object.assign(prefs.tripSettings,{end,mode:f.has('auto')?'auto':'off',timezone:f.get('timezone')});tripHomeOverride=false;save();render()};if($('#diningForm')){$('#diningForm').onsubmit=e=>{e.preventDefault();if(prefs.dining.length>=100)return toast('Keep up to 100 dining entries.');const f=new FormData(e.target);prefs.dining.push({id:crypto.randomUUID(),...Object.fromEntries(f.entries())});save();render()};box.querySelectorAll('[data-dining-remove]').forEach(b=>b.onclick=()=>{prefs.dining=prefs.dining.filter(r=>r.id!==b.dataset.diningRemove);save();render()})}let editId=null;$('#dvcForm').onsubmit=e=>{e.preventDefault();if(!editId&&prefs.dvc.length>=20)return toast('Keep up to 20 contract snapshots.');const f=new FormData(e.target),c={id:editId||crypto.randomUUID(),name:f.get('name'),month:Number(f.get('month')),year:Number(f.get('year')),current:Number(f.get('current')),banked:Number(f.get('banked')),borrowed:Number(f.get('borrowed')),borrowReminder:f.get('borrowReminder'),updated:tripToday()};if([c.current,c.banked,c.borrowed].some(n=>!Number.isInteger(n)||n<0))return;prefs.dvc=[...prefs.dvc.filter(x=>x.id!==c.id),c];save();render()};box.querySelectorAll('[data-dvc-edit]').forEach(b=>b.onclick=()=>{const c=prefs.dvc.find(x=>x.id===b.dataset.dvcEdit);editId=c.id;for(const [k,v]of Object.entries(c)){const input=$('#dvcForm').elements.namedItem(k);if(input)input.value=v}$('#dvcForm').scrollIntoView({block:'center'});$('#dvcForm').elements.namedItem('name').focus()});box.querySelectorAll('[data-dvc-remove]').forEach(b=>b.onclick=()=>{prefs.dvc=prefs.dvc.filter(c=>c.id!==b.dataset.dvcRemove);save();render()});$('#dvcCalendar').onclick=()=>downloadText('disney-dvc-reminders.ics',dvcCalendar(),'text/calendar')}
if($('#saveTripDayPark'))$('#saveTripDayPark').onclick=()=>{selected=$('#tripDayPark').value;prefs.tripSettings.parkByDate[tripToday()]=selected;save();render();loadPark(true)};if($('#dreamHome'))$('#dreamHome').onclick=()=>{tripHomeOverride=true;render()};if(page==='home'&&tripIsActive()&&tripHomeOverride&&!$('#backTripDay')){const b=document.createElement('button');b.id='backTripDay';b.textContent='Return to today’s park dashboard';b.onclick=()=>{tripHomeOverride=false;alignTripPark();render();loadPark(true)};$('#main').prepend(b)}}

const tripNavigatePrevious=navigateStage2;const navigateStage3=function(p){tripNavigatePrevious(p);if(p==='home'&&tripIsActive())loadPark()};


/* push-client.js */
/* Device-specific Web Push enrollment. No permission prompt before a user gesture. */
function pushWatchKey(w){return w.provider+':'+w.parkId+':'+w.rideId}
function currentPushWatches(){const qp=queuePark();return getItems().filter(r=>prefs.favorites.includes(r.id)&&prefs.rideAlerts[r.id]).flatMap(r=>{const queue=r.id.startsWith('qt-');if(queue&&!qp)return [];return [{provider:queue?'queue':'themeparks',parkId:String(queue?qp.id:selected),rideId:queue?r.id.slice(3):r.id,threshold:prefs.rideAlerts[r.id].threshold,name:r.name.slice(0,100)}]})}
async function pushRequest(path,method='GET',body){const r=await fetch('/api/push/'+path,{method,headers:{'X-Sparkle-Key':stationAccessCode,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await r.json();if(!r.ok)throw Error(data.error||'Push service unavailable');return data}
function keyBytes(s){return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-s.length%4)%4)),c=>c.charCodeAt(0))}
function pushDialog(){const d=$('#dialog');d.onclose=null;d.innerHTML=`<h2>A little magic, even in your pocket.</h2><p>Checks saved ride thresholds about every five minutes, even when this app is closed. Needs the separate scheduled Worker, D1 and VAPID setup. On iPhone/iPad, add this app to the Home Screen, open it there, then enable notifications.</p><p>Choose a park, star rides and set wait alerts first. Saving updates this park’s watchlist on this device; other saved parks are retained. Changes on another device do not change this phone’s subscription until you save here.</p><label>Monitor for<select id="pushDuration"><option value="1">1 day</option><option value="7">7 days</option><option value="30">30 days</option><option value="90">90 days</option></select></label><div class="toolbar"><button id="pushEnable">Enable / update this park’s pocket alerts</button><button id="pushStatus">Check service & device status</button><button id="pushDisable">Turn off this device’s pocket alerts</button></div><p id="pushResult" role="status">${currentPushWatches().length} eligible starred ride alerts in ${esc(parkName())}. No subscription yet verified.</p><p>Up to 30 watches per device, 12 parks and 10 devices per station. Fresh open rides only; repeat alerts require a rise to/above the threshold and another drop, with a 30-minute cooldown. Delivery depends on your browser, network and Focus settings. This is not a guarantee of a short wait when you arrive.</p><button id="pushClose">Close</button>`;d.showModal();$('#pushClose').onclick=()=>d.close();const status=$('#pushResult');const supported=()=>{if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Web Push is not supported in this browser. On iPhone use the installed Home Screen app.');if(!stationAccessCode)throw Error('Enter the station code in Connected features first.')};const run=async fn=>{d.querySelectorAll('button').forEach(b=>b.disabled=true);try{status.textContent=await fn()}catch(e){status.textContent=e.message}finally{d.querySelectorAll('button').forEach(b=>b.disabled=false)}};
$('#pushStatus').onclick=()=>run(async()=>{supported();const cfg=await pushRequest('config'),reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();let state=null;if(sub)state=await pushRequest('device','POST',{endpoint:sub.endpoint});return `Public key: ${cfg.publicKey?'configured':'missing'}. Last scheduled check: ${cfg.lastRun?new Date(cfg.lastRun).toLocaleString():'not recorded'}. ${cfg.lastError||''} ${state?.device?'This device: '+state.device.watches.length+' watches; expires '+new Date(state.device.expires).toLocaleString(): 'No saved device subscription.'}`});
$('#pushEnable').onclick=()=>run(async()=>{supported();if(await Notification.requestPermission()!=='granted')throw Error('Notification permission was not granted.');const cfg=await pushRequest('config');if(!cfg.publicKey)throw Error('Owner setup needed: VAPID_PUBLIC_KEY in Pages.');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(cfg.publicKey)});const old=await pushRequest('device','POST',{endpoint:sub.endpoint});const qp=queuePark(),watches=(old.device?.watches||[]).filter(w=>!(w.provider==='themeparks'&&w.parkId===selected)&&!(w.provider==='queue'&&w.parkId===String(qp?.id)));watches.push(...currentPushWatches());if(!watches.length)throw Error('Star a ride and set its wait threshold first.');if(watches.length>30)throw Error('Maximum 30 saved ride watches. Turn off this device to reset its watchlist.');const expires=Date.now()+Number($('#pushDuration').value)*86400000;await pushRequest('subscribe','POST',{subscription:sub.toJSON(),watches,expires});return `Saved ${watches.length} watches for this device through ${new Date(expires).toLocaleString()}. ${cfg.lastRun?'Scheduled service has checked in.':'No scheduled check recorded yet—verify Worker setup.'}`});
$('#pushDisable').onclick=()=>run(async()=>{supported();const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await pushRequest('unsubscribe','POST',{endpoint:sub.endpoint});await sub.unsubscribe()}return 'Pocket alerts disabled for this device. In-app alerts are unchanged.'})}


/* refinements.js */
/* Keep the visual system; selectively adapt resort-picker and music workflows. */
prefs.favoriteResorts ||= [];prefs.showCharacters ??= true;prefs.loungeStyle ||= 'auto';
const refinedRender=renderStage4,refinedBind=bindExperience,refinedPiano=pianoStage3,refinedSettings=settingsStage4;
const FRIENDS={trio:{src:'assets/trio.jpg',name:'Donald, Goofy & Pluto'},belle:{src:'assets/belle.jpg',name:'Belle'},tiana:{src:TIANA,name:'Tiana'},stitch:{src:STITCH,name:'Stitch'}};
let melody=null,melodyPosition=0,melodyFinishedAt=null;
function resortPianoStyle(n=prefs.resort){return /French/.test(n)?'jazz':/Riverside|Art of Animation/.test(n)?'swing':/Grand Floridian|BoardWalk|Beach Club/.test(n)?'ragtime':/Polynesian|Aulani/.test(n)?'hawaiian':/Wilderness|Boulder|Copper/.test(n)?'frontier':/Caribbean|Old Key West/.test(n)?'island':/Coronado|Gran Destino/.test(n)?'latin':/Contemporary|Bay Lake/.test(n)?'electro':/Animal Kingdom|Jambo|Kidani|Yacht/.test(n)?'ballad':'lounge'}
function selectedPianoStyle(){return prefs.loungeStyle==='auto'?resortPianoStyle():prefs.loungeStyle}
function musicLabel(){return melody?'Playing melody sketch: '+melody.n:LOUNGE.on?'Playing '+selectedPianoStyle()+' piano':'Piano paused'}
function updateMusicLabel(){const status=$('#melodyStatus');if(status)status.textContent=musicLabel();const button=$('#loungePlay');if(button)button.textContent=LOUNGE.on?'Pause the lounge set':'Start the lounge set'}
LOUNGE.tick=function(){if(!this.on||!loungeAC)return;const sty=PRESETS[selectedPianoStyle()]||PRESETS.lounge,hol=prefs.loungeStyle==='auto'&&seasonNow()==='christmas',major=melody||hol||sty.maj,prog=major?MAJPROG:MINPROG,scale=major?MAJSCALE:MINSCALE,spb=60/(melody?96:hol?104:sty.bpm)/2;
 // Avoid a burst of overdue notes after a backgrounded tab resumes.
 if(this.next<loungeAC.currentTime-.5)this.next=loungeAC.currentTime+.05;
 if(melodyFinishedAt!==null&&loungeAC.currentTime>=melodyFinishedAt){melody=null;melodyFinishedAt=null;updateMusicLabel()}
 while(this.next<loungeAC.currentTime+.4){const t=this.next,e=this.step%8,chord=prog[this.bar%4];if(e===0){this.note(chord[0]-12,t,spb*7,.35,true);chord[1].forEach(n=>this.note(n,t+spb*(2+this.seed%2),spb*3,.065))}if(e===4)this.note(chord[0]-12+(this.seed%3===0?7:0),t,spb*3,.24,true);
 let n=0;if(melody){n=melody.m[melodyPosition++]||0;if(melodyPosition>=melody.m.length&&melodyFinishedAt===null)melodyFinishedAt=t+spb*2;}else if(hol){const c=CAROLS[carolN%CAROLS.length];n=c[carolPos++%c.length];if(carolPos>=c.length){carolPos=0;carolN++}}else{const r=Math.abs(Math.sin(this.seed*9301+this.step*49297)%1);if(r>.38)n=scale[Math.floor(r*scale.length)%scale.length]}
 if(n)this.note(n+12,t,spb*1.9,.14*sty.vel);this.next+=spb*2*(e%2===0?sty.swing:1-sty.swing);this.step++;if(this.step%8===0)this.bar++;}}
function playMelody(index){const song=PDSONGS[index];if(!song)return;try{requestPlayer?.pauseVideo?.();pianoPlaying?.pause?.();melody=song;melodyPosition=0;melodyFinishedAt=null;LOUNGE.step=0;LOUNGE.bar=0;LOUNGE.start();updateMusicLabel()}catch{LOUNGE.stop();melody=null;toast('Audio could not start in this browser. Try a recorded performance.')}}
const pianoStage4=function(){return refinedPiano().replace(/<select id="loungeStyle"[\s\S]*?<\/select>/,`<select id="loungeStyle" aria-label="Piano style">${['auto',...Object.keys(PRESETS)].map(v=>`<option value="${v}" ${prefs.loungeStyle===v?'selected':''}>${v==='auto'?'Follow my resort & season':v.charAt(0).toUpperCase()+v.slice(1)+' piano'}</option>`).join('')}</select>`)+`<section class="card house-songbook"><p class="eyebrow">AT THE HOUSE PIANO</p><h2>A little something you know.</h2><p class="muted">Choose a melody sketch played by the browser’s piano engine. Recorded requests above play their own performances.</p><div class="songbook-buttons">${PDSONGS.map((s,i)=>`<button data-melody="${i}">${esc(s.n)}</button>`).join('')}</div><p id="melodyStatus" role="status">${esc(musicLabel())}</p><button id="stopMelody">Pause piano</button><p class="muted small">Synthesized piano, with bass and chord accompaniment. These are short melody arrangements, not complete concert recordings or official resort soundtracks.</p></section>`};
const settingsStage5=function(){return refinedSettings().replace('<div class="toolbar"><button class="primary">Save my sparkle',`<label class="character-setting"><input type="checkbox" name="showCharacters" ${prefs.showCharacters?'checked':''}> Show character moments around the app</label><div class="toolbar"><button class="primary">Save my sparkle`)};
function matchingResorts(query='',group='all'){const q=query.trim().toLowerCase();return resorts.filter(n=>(group==='all'||resortGroup(n)===group)&&(n.toLowerCase().includes(q)||resortGroup(n).toLowerCase().includes(q))).sort((a,b)=>Number(prefs.favoriteResorts.includes(b))-Number(prefs.favoriteResorts.includes(a))||a.localeCompare(b))}
function openResortPicker(){const d=$('#dialog');d.innerHTML=`<div class="sectionhead"><div><p class="eyebrow">FIND YOUR HAPPY PLACE</p><h2>Where are we staying?</h2></div><button id="closeResorts" aria-label="Close resort picker">✕</button></div><div class="toolbar"><input id="resortSearch" placeholder="Search a resort, villas or destination…" aria-label="Search resorts"><select id="resortRegion" aria-label="Resort destination"><option value="all">Every destination</option>${[...new Set(resorts.map(resortGroup))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><p id="resortCount" role="status"></p><div id="resortPickerGrid"></div>`;d.showModal();$('#closeResorts').onclick=()=>d.close();const update=()=>{const found=matchingResorts($('#resortSearch').value,$('#resortRegion').value);$('#resortCount').textContent=found.length+' resorts · favorites appear first';$('#resortPickerGrid').innerHTML=found.map(n=>{const r=resortIdentity(n),saved=prefs.favoriteResorts.includes(n);return `<article class="resort-choice ${n===prefs.resort?'selected':''}"><button class="resort-pick" data-pick-resort="${esc(n)}">${r.photo?`<img loading="lazy" src="${esc(r.photo)}" alt="">`:'<div class="resort-photo-placeholder">Your next happy place</div>'}<h3>${esc(n)}</h3><p>${esc(resortGroup(n))}</p><small>${n===prefs.resort?'Your current resort':'Choose this resort →'}</small></button><button class="resort-save" data-save-resort="${esc(n)}" aria-pressed="${saved}" aria-label="${saved?'Unfavorite':'Favorite'} ${esc(n)}">${saved?'★':'☆'}</button></article>`}).join('')||'<p class="muted">No matching resorts. Try a destination or a shorter name.</p>';d.querySelectorAll('[data-pick-resort]').forEach(b=>b.onclick=()=>{prefs.resort=b.dataset.pickResort;prefs.theme='auto';save();d.close();render();toast('Welcome to '+prefs.resort)});d.querySelectorAll('[data-save-resort]').forEach(b=>b.onclick=()=>{const n=b.dataset.saveResort;prefs.favoriteResorts=prefs.favoriteResorts.includes(n)?prefs.favoriteResorts.filter(x=>x!==n):[...prefs.favoriteResorts,n];save();update()});d.querySelectorAll('img').forEach(im=>im.onerror=()=>{im.style.display='none'})};$('#resortSearch').oninput=update;$('#resortRegion').onchange=update;update();$('#resortSearch').focus()}
function characterMoment(p){const config={parks:['trio','A few familiar faces.','Looking for a character hello? Explore the meet-and-greet readings supplied by the park feed.','Explore character waits','characters'],piano:['tiana','An evening with a little soul.','Pull up a chair. Choose a familiar melody, or settle in for your recorded request.','Browse the songbook','songbook'],vacation:['belle','Your next chapter is waiting.','A date on the calendar. A few more sleeps. A little more magic to look forward to.','Find your resort','resort'],multiview:['stitch','A little park-hopping mischief.','Make room for another view, and choose one soundtrack at a time.','Visit the fireworks terrace','terrace'],photos:['trio','The best souvenirs are your memories.','Your favorite faces and favorite days deserve a place in the story.','Plan another chapter','vacation']};const c=config[p];if(!prefs.showCharacters||!c)return '';const f=FRIENDS[c[0]];return `<section class="character-moment"><img loading="lazy" src="${esc(f.src)}" alt="${esc(f.name)}"><div><p class="eyebrow">A LITTLE CHARACTER. A LITTLE MAGIC.</p><h2>${c[1]}</h2><p>${c[2]}</p><button data-character-action="${c[4]}">${c[3]} →</button></div></section>`}
bindExperience=function(){refinedBind();const f=$('#settingsForm');if(f){const submit=f.onsubmit;f.onsubmit=e=>{prefs.showCharacters=new FormData(f).has('showCharacters');submit(e)}}if($('#loungeStyle'))$('#loungeStyle').onchange=e=>{prefs.loungeStyle=e.target.value;save();updateMusicLabel()};document.querySelectorAll('[data-melody]').forEach(b=>b.onclick=()=>playMelody(+b.dataset.melody));if($('#stopMelody'))$('#stopMelody').onclick=()=>{LOUNGE.stop();melody=null;melodyFinishedAt=null;updateMusicLabel()};const b=$('#loungePlay');if(b){const click=b.onclick;b.onclick=()=>{try{click();updateMusicLabel()}catch{toast('Audio is unavailable in this browser.')}}}};
const renderStage5=function(){if(page!=='piano'){melody=null;melodyFinishedAt=null}refinedRender();if(page==='resort'&&!$('#browseResorts')){const b=document.createElement('button');b.id='browseResorts';b.textContent='Browse resorts';b.onclick=openResortPicker;$('#resortQuick')?.parentNode.append(b)}installMagic();installGuide();installFamilyTools();const main=$('#main');if(main&&!$('#characterMoment')){const html=characterMoment(page);if(html){const el=document.createElement('div');el.id='characterMoment';el.innerHTML=html;main.prepend(el);el.querySelectorAll('[data-character-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.characterAction;if(a==='characters'){filter='characters';navigate('parks')}else if(a==='songbook')$('.house-songbook')?.scrollIntoView({behavior:'smooth',block:'start'});else navigate(a)});el.querySelectorAll('img').forEach(im=>im.onerror=()=>{im.style.display='none'})}}};


/* Family welcome, character parade, hidden-Mickey hunt and personal trip notebook. */
prefs.hiddenMickeys ||= [];prefs.tripPlan ||= {days:[],notes:''};
const HUNT_PAGES=['home','parks','resort','terrace','multiview','piano','vacation','planner','settings'];
tabs.splice(tabs.findIndex(x=>x[0]==='vacation')+1,0,['planner','✎','Plan your magic']);
function familyGreeting(){const family=prefs.family==='Your family'?'your family':prefs.family;return `Hi everybody! I want to welcome ${family} to ${prefs.stationTitle}! We are all here to give you a little sparkle back virtually, since you can’t be with us today.`}
function plannerMarkup(){return title('Let’s plan a little magic.','A family trip notebook for your must-dos, quieter moments and next big adventure.','PLAN YOUR MAGIC')+`<section class="card"><p class="eyebrow">${esc(prefs.family)} · ${esc(prefs.resort)}</p><h2>One wonderful day at a time.</h2><form id="planDayForm" class="formgrid"><label>Date<input name="date" type="date" required value="${esc(prefs.date)}"></label><label>Destination<input name="park" required maxlength="100" list="tripParks" placeholder="Magic Kingdom, EPCOT, resort day…"><datalist id="tripParks">${['Magic Kingdom','EPCOT','Disney’s Hollywood Studios','Disney’s Animal Kingdom','Disneyland Park','Disney California Adventure','Resort day'].map(n=>`<option value="${esc(n)}">`).join('')}</datalist></label><label>Our must-do<input name="priority" maxlength="180" placeholder="A ride, character or favorite snack"></label><label>Dining / rest / celebration notes<input name="notes" maxlength="400" placeholder="Afternoon pool break, birthday dinner…"></label><button class="primary">Add to our trip</button></form><p class="muted small">Your personal plan, saved in this browser. This does not book dining, tickets or park reservations.</p></section><div class="trip-days">${prefs.tripPlan.days.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`<article class="card"><p class="eyebrow">${esc(d.date)}</p><h2>${esc(d.park)}</h2><p><strong>Must-do:</strong> ${esc(d.priority||'Leave room for a surprise')}</p><p>${esc(d.notes)}</p><p class="muted small">Leave time for meals, travel between parks and a rest break. Check current park hours before you go.</p><button data-plan-remove="${esc(d.id)}">Remove day</button></article>`).join('')||'<p class="muted">Your next chapter starts with one day.</p>'}</div><section class="card"><h2>Little things worth remembering</h2><form id="tripNotesForm"><label>Packing, accessibility needs and family reminders<textarea name="notes" rows="5" maxlength="5000">${esc(prefs.tripPlan.notes)}</textarea></label><button>Save reminders</button></form><div class="toolbar"><button id="exportTrip">Download our plan</button><button data-page="resort">Check park hours</button><button data-page="insights">Crowd calendars & planning links</button></div></section>`}
function characterParade(){const people=[{src:MICKEY_CLASSIC,name:'Mickey & Minnie'},FRIENDS.trio,FRIENDS.stitch,FRIENDS.belle,FRIENDS.tiana];return `<div class="character-parade" aria-label="Your Disney friends">${people.map(f=>`<figure><div class="character-portrait"><span class="mickey-mark" aria-hidden="true"></span><img src="${esc(f.src)}" alt="${esc(f.name)}" loading="lazy"></div><figcaption>${esc(f.name)}</figcaption></figure>`).join('')}</div>`}
function welcomeDialog(){const d=$('#dialog');d.innerHTML=`<p class="eyebrow">A HELLO FOR YOUR FAMILY</p><h2>Welcome, ${esc(prefs.family)}.</h2><img class="welcome-mickey-photo" src="${MICKEY_CLASSIC}" alt="Mickey and Minnie"><p class="welcome-script">${esc(familyGreeting())}</p><div class="toolbar"><button id="speakWelcome">Hear browser-voice welcome</button><button id="stopWelcome">Stop</button><button id="closeWelcome">Close</button></div><p class="muted small">Browser narration uses your device’s voice, not Mickey’s voice. For Mickey’s voice, choose your own recording below. A recording plays as supplied; changing the family name does not rewrite recorded audio.</p><label>Mickey / family welcome recording<input id="welcomeFile" type="file" accept="audio/*"></label><h3>Hear Mickey’s voice sample</h3><audio controls preload="none" src="assets/mickey-sample.mp3"></audio><p class="muted small">Fish Audio model preview · fixed sample, not a personalized family greeting.</p><div id="welcomeAudioMount"></div><p id="welcomeStatus" role="status"></p>`;d.showModal();const status=$('#welcomeStatus'),audioMount=$('#welcomeAudioMount');let player=null,closed=false;const stop=()=>{window.speechSynthesis?.cancel();d.querySelectorAll('audio').forEach(a=>a.pause());player?.pause()};$('#stopWelcome').onclick=stop;$('#closeWelcome').onclick=()=>{stop();d.close()};d.onclose=()=>{closed=true;stop()};$('#speakWelcome').onclick=()=>{stop();if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){status.textContent='Browser speech is unavailable. Choose an audio recording.';return}const speech=new window.SpeechSynthesisUtterance(familyGreeting());speech.rate=.93;speech.onerror=()=>status.textContent='Voice could not start. Try a recording.';window.speechSynthesis.speak(speech);status.textContent='Playing a browser-voice welcome.'};const mount=async()=>{if(!prefs.welcomeRecording)return;try{const src=await mediaURL(prefs.welcomeRecording);if(closed||!audioMount.isConnected)return;audioMount.innerHTML='<audio controls id="welcomeAudio"></audio>';player=$('#welcomeAudio');player.src=src;player.onplay=()=>window.speechSynthesis?.cancel();player.onerror=()=>status.textContent='This recording could not play. Choose another audio file.'}catch{status.textContent='Choose the recording again on this device.'}};$('#welcomeFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>50*1024*1024){status.textContent='Choose an audio recording under 50 MB.';return}try{stop();const key='local:'+crypto.randomUUID();await mediaDB('put',key,f);prefs.welcomeRecording=key;save();await mount();status.textContent='Welcome recording saved on this device. Press Play to hear it.'}catch{status.textContent='Unable to save the recording. Device storage may be full.'}};mount();installVoiceStudio(d)}
function tripText(){return [prefs.stationTitle,prefs.family,prefs.resort,'',...prefs.tripPlan.days.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(d=>`${d.date} — ${d.park}\nMust-do: ${d.priority}\nNotes: ${d.notes}\n`),'Reminders:',prefs.tripPlan.notes].join('\n')}
function installMagic(){const main=$('#main');if(!main)return;if(page==='planner'){main.innerHTML=plannerMarkup();bind();$('#planDayForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));prefs.tripPlan.days.push({...d,id:crypto.randomUUID()});save();render()};$('#tripNotesForm').onsubmit=e=>{e.preventDefault();prefs.tripPlan.notes=new FormData(e.target).get('notes');save();toast('Trip reminders saved.')};document.querySelectorAll('[data-plan-remove]').forEach(b=>b.onclick=()=>{prefs.tripPlan.days=prefs.tripPlan.days.filter(d=>d.id!==b.dataset.planRemove);save();render()});$('#exportTrip').onclick=()=>{const u=URL.createObjectURL(new Blob([tripText()],{type:'text/plain'})),a=document.createElement('a');a.href=u;a.download='our-disney-trip.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}}
 if(prefs.showCharacters&&!$('#characterParade')&&page!=='checkin'){const el=document.createElement('section');el.id='characterParade';el.innerHTML=characterParade();main.prepend(el);el.querySelectorAll('img').forEach(im=>im.onerror=()=>{im.style.display='none';im.parentNode.title='Photo unavailable; character name shown below'})}
 if(!$('#familyWelcome')){const b=document.createElement('button');b.id='familyWelcome';b.textContent='✧ Family welcome';b.onclick=welcomeDialog;document.querySelector('header>div').prepend(b)}
 if(HUNT_PAGES.includes(page)&&!$('#hiddenMickey')){const b=document.createElement('button');b.id='hiddenMickey';b.className='hidden-mickey '+(prefs.hiddenMickeys.includes(page)?'found':'');b.style.right=(3+HUNT_PAGES.indexOf(page)*7%40)+'%';b.setAttribute('aria-label','Find the hidden Mickey on this screen');b.innerHTML='<span class="mickey-mark" aria-hidden="true"></span>';b.onclick=()=>{if(!prefs.hiddenMickeys.includes(page)){prefs.hiddenMickeys.push(page);save()}b.classList.add('found');toast('You found a hidden Mickey! '+prefs.hiddenMickeys.length+' of '+HUNT_PAGES.length+' discovered.');const t=$('#huntProgress');if(t)t.textContent=prefs.hiddenMickeys.length+' / '+HUNT_PAGES.length+' hidden Mickeys found'};const area=$('#main .intro')||main;area.append(b)}
 if(page==='home'&&!$('#huntProgress')){const p=document.createElement('p');p.id='huntProgress';p.className='hunt-progress';p.textContent=prefs.hiddenMickeys.length+' / '+HUNT_PAGES.length+' hidden Mickeys found';main.append(p)}
}


function render(...args){const active=document.activeElement,key=active?.id;const result=renderStage5(...args);if(key){const next=document.getElementById(key);if(next)next.focus({preventScroll:true})}return result}
function bind(...args){const result=bindStage2(...args);return result}
function home(...args){const result=homeStage4(...args);return result}
function parkPage(...args){const result=parkPageStage2(...args);return result}
function resortPage(...args){const result=resortPageStage4(...args);return result}
function settings(...args){const result=settingsStage5(...args);return result}
function piano(...args){const result=pianoStage4(...args);return result}
function checkin(...args){const result=checkinStage2(...args);return result}
function terrace(...args){const result=terraceStage4(...args);return result}
function multiview(...args){const result=multiviewStage2(...args);return result}
function navigate(...args){const result=navigateStage3(...args);return result}
bootFamilyTools();if(!prefs.checkedIn)page='checkin';render();initData();loadVideoTitles();
